package com.github.ilee2.hitstats;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import lombok.Getter;

/**
 * The contexts and fights matching a {@link HistoryFilter}, folded into one histogram and one
 * set of counters. Built on the client thread, read on the Swing thread; every array and list
 * in it is a copy.
 *
 * <p>Killing blows can be charted or left out. Only the statistics that describe the shape of
 * the distribution follow that choice: the histogram, the averages per hitsplat, the highest hit
 * and the max-hit rate. Attacks, hitsplats, total damage, accuracy, DPS and wasted ticks measure
 * what happened, and always count every hit.
 */
@Getter
public class Aggregate
{
	private static final double SECONDS_PER_TICK = 0.6;

	/** The histogram as charted: every hitsplat, or every hitsplat but the killing blows. */
	private final int[] counts;

	/** Killing blows by damage, whether or not they are also folded into {@link #counts}. */
	private final int[] killCounts;

	private final boolean killingBlowsIncluded;
	private final int killingBlows;
	private final int killingBlowDamage;

	private final int attacks;

	/** Every hitsplat, killing blows included. */
	private final int hitsplats;

	private final int splashes;

	/** Max hits among the charted hitsplats. */
	private final int maxHits;

	private final int wastedTicks;
	private final int activeTicks;
	private final int fights;
	private final int kills;
	private final long killTicks;
	private final int magicAttacks;

	/** Hitsplats from magic contexts, which together with the splashes are the magic attempts. */
	private final int magicHitsplats;

	private final int protectedAttacks;
	private final List<ContextStats> contexts;

	Aggregate(List<ContextStats> matched, List<KillRecord> matchedFights)
	{
		this(matched, matchedFights, true);
	}

	Aggregate(List<ContextStats> matched, List<KillRecord> matchedFights, boolean includeKillingBlows)
	{
		int width = 1;
		for (ContextStats c : matched)
		{
			width = Math.max(width, Math.max(c.getCounts().length, c.getKillCounts().length));
		}

		final int[] histogram = new int[width];
		final int[] kills = new int[width];
		int attackTotal = 0;
		int hitsplatTotal = 0;
		int splashTotal = 0;
		int maxHitTotal = 0;
		int killingBlowTotal = 0;
		int killingBlowMaxHits = 0;
		int wasted = 0;
		int active = 0;
		int magic = 0;
		int magicSplats = 0;
		int protectedAttacks = 0;

		final List<ContextStats> copies = new ArrayList<>(matched.size());
		for (ContextStats c : matched)
		{
			final ContextStats copy = c.copy();
			copies.add(copy);

			final int[] counts = copy.getCounts();
			for (int d = 0; d < counts.length; d++)
			{
				histogram[d] += counts[d];
			}
			final int[] killCounts = copy.getKillCounts();
			for (int d = 0; d < killCounts.length; d++)
			{
				kills[d] += killCounts[d];
			}
			attackTotal += copy.getAttacks();
			hitsplatTotal += copy.getHitsplats();
			splashTotal += copy.getSplashes();
			maxHitTotal += copy.getMaxHits();
			killingBlowTotal += copy.getKillingBlows();
			killingBlowMaxHits += copy.getKillingBlowMaxHits();
			wasted += copy.getWastedTicks();
			active += copy.getActiveTicks();
			final CombatContext context = copy.getContext();
			if (context != null)
			{
				if (context.getCombatStyle() == CombatStyle.MAGIC)
				{
					magic += copy.getAttacks();
					magicSplats += copy.getHitsplats();
				}
				if (context.isStyleProtected())
				{
					protectedAttacks += copy.getAttacks();
				}
			}
		}
		copies.sort(Comparator.comparingInt(ContextStats::getAttacks).reversed());

		int killingBlowDamageTotal = 0;
		for (int d = 1; d < width; d++)
		{
			killingBlowDamageTotal += d * kills[d];
			if (includeKillingBlows)
			{
				histogram[d] += kills[d];
			}
		}

		int fightCount = 0;
		int killCount = 0;
		long killTickTotal = 0;
		for (KillRecord f : matchedFights)
		{
			fightCount++;
			if (f.isKilled())
			{
				killCount++;
				killTickTotal += f.getDurationTicks();
			}
		}

		this.counts = histogram;
		this.killCounts = kills;
		this.killingBlowsIncluded = includeKillingBlows;
		this.killingBlows = killingBlowTotal;
		this.killingBlowDamage = killingBlowDamageTotal;
		this.attacks = attackTotal;
		this.hitsplats = hitsplatTotal;
		this.splashes = splashTotal;
		this.maxHits = includeKillingBlows ? maxHitTotal : maxHitTotal - killingBlowMaxHits;
		this.wastedTicks = wasted;
		this.activeTicks = active;
		this.fights = fightCount;
		this.kills = killCount;
		this.killTicks = killTickTotal;
		this.magicAttacks = magic;
		this.magicHitsplats = magicSplats;
		this.protectedAttacks = protectedAttacks;
		this.contexts = Collections.unmodifiableList(copies);
	}

	static Aggregate empty()
	{
		return new Aggregate(Collections.emptyList(), Collections.emptyList(), true);
	}

	public boolean isEmpty()
	{
		return attacks == 0 && hitsplats == 0 && splashes == 0;
	}

	/** Killing blows the chart is not showing: zero when they are included. */
	public int getExcludedKillingBlows()
	{
		return killingBlowsIncluded ? 0 : killingBlows;
	}

	/** Every point of damage dealt, whether or not the killing blows are charted. */
	public int getTotalDamage()
	{
		return getChartedDamage() + (killingBlowsIncluded ? 0 : killingBlowDamage);
	}

	/** Damage summed over the charted histogram. */
	public int getChartedDamage()
	{
		int total = 0;
		for (int d = 1; d < counts.length; d++)
		{
			total += d * counts[d];
		}
		return total;
	}

	/** Hitsplats in the charted histogram, zeros included. */
	public int getChartedHitsplats()
	{
		return hitsplats - getExcludedKillingBlows();
	}

	/** Hitsplats of zero damage: the blue "0" for a melee or ranged miss, or a magic hit that rolled 0. */
	public int getZeroHits()
	{
		return counts.length > 0 ? counts[0] : 0;
	}

	/** Hitsplats that did damage, killing blows included: a killing blow always landed. */
	public int getLandedHits()
	{
		return hitsplats - getZeroHits();
	}

	/** Every attempt that could have done damage: hitsplats plus splashes. */
	public int getAttempts()
	{
		return hitsplats + splashes;
	}

	/** The tallest bar among the damage values, which is what the chart is scaled to. */
	public int getDamagePeak()
	{
		int peak = 0;
		for (int d = 1; d < counts.length; d++)
		{
			peak = Math.max(peak, counts[d]);
		}
		return peak;
	}

	public int getHighestHit()
	{
		for (int d = counts.length - 1; d > 0; d--)
		{
			if (counts[d] > 0)
			{
				return d;
			}
		}
		return 0;
	}

	/** Mean damage per attack, splashes, zeros and killing blows all included. */
	public double getAveragePerAttack()
	{
		return attacks == 0 ? 0 : (double) getTotalDamage() / attacks;
	}

	/** Mean damage per charted hitsplat, zeros included, splashes excluded. */
	public double getAveragePerHitsplat()
	{
		final int charted = getChartedHitsplats();
		return charted == 0 ? 0 : (double) getChartedDamage() / charted;
	}

	/** Mean damage of the charted hits that did damage. */
	public double getAveragePerLandedHit()
	{
		final int landed = getChartedHitsplats() - getZeroHits();
		return landed == 0 ? 0 : (double) getChartedDamage() / landed;
	}

	/**
	 * Share of attempts that did damage. Killing blows count: whether a hit landed was decided
	 * before its damage was capped, so leaving them out would understate accuracy.
	 */
	public double getAccuracy()
	{
		final int attempts = getAttempts();
		return attempts == 0 ? 0 : (double) getLandedHits() / attempts;
	}

	/**
	 * Share of magic attempts that splashed: splashes over magic hitsplats plus splashes. Melee
	 * and ranged hitsplats in the same filter are left out, so an "All styles" view at a boss you
	 * also meleed does not water the rate down.
	 */
	public double getSplashRate()
	{
		final int attempts = magicHitsplats + splashes;
		return attempts == 0 ? 0 : (double) splashes / attempts;
	}

	/** Share of attacks made into a target that was praying against the style used. */
	public double getProtectedShare()
	{
		return attacks == 0 ? 0 : (double) protectedAttacks / attacks;
	}

	public double getMaxHitRate()
	{
		final int charted = getChartedHitsplats();
		return charted == 0 ? 0 : (double) maxHits / charted;
	}

	public double getDps()
	{
		return activeTicks == 0 ? 0 : getTotalDamage() / (activeTicks * SECONDS_PER_TICK);
	}

	public double getWastedShare()
	{
		return activeTicks == 0 ? 0 : (double) wastedTicks / activeTicks;
	}

	public double getWastedPerAttack()
	{
		return attacks == 0 ? 0 : (double) wastedTicks / attacks;
	}

	public double getAverageKillSeconds()
	{
		return kills == 0 ? 0 : killTicks * SECONDS_PER_TICK / kills;
	}
}

package com.github.ilee2.hitstats;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * Pairs attack animations with the hitsplats and splashes they produce. Pure tick arithmetic, no
 * client access, so it can be unit tested.
 *
 * <p>Rules:
 * <ul>
 *   <li>An animation inside the cooldown of the last committed attack is not an attack (it is a
 *       block, an eat, or similar) and is dropped.</li>
 *   <li>A hit on an NPC prefers the oldest pending attack on that NPC that has not resolved yet,
 *       or one that resolved on this same tick (multi-hit weapons). Failing that it takes any
 *       unresolved pending attack (area-of-effect spill onto a secondary target), then any attack
 *       resolved on this tick.</li>
 *   <li>A splash only matches a magic attack on that same NPC. The splash graphic carries no
 *       owner, so it may have been another player's: an attack resolved by a splash stays open to
 *       a later hit of ours on the same NPC, and that hit is the attack's real result. The
 *       tracker then takes the splash back.</li>
 *   <li>Committing an attack retroactively drops uncommitted animations that fell inside its
 *       cooldown.</li>
 *   <li>Pending attacks older than the window are expired; those never matched are counted.</li>
 * </ul>
 */
public class AttackMatcher
{
	private int windowTicks;
	private final Deque<PendingAttack> pending = new ArrayDeque<>();

	@Nullable
	private PendingAttack lastCommitted;

	@Getter
	private int rejectedByCooldown;

	@Getter
	private int expiredUnmatched;

	public AttackMatcher(int windowTicks)
	{
		this.windowTicks = windowTicks;
	}

	/** Changes the window without dropping what is pending, so a config edit mid-fight loses nothing. */
	public void setWindowTicks(int windowTicks)
	{
		this.windowTicks = windowTicks;
	}

	public int getWindowTicks()
	{
		return windowTicks;
	}

	/**
	 * @return whether an animation on {@code tick} falls inside the cooldown of the last committed
	 * attack, and so would be rejected by {@link #offer}. Lets the caller skip building a context
	 * it is about to throw away.
	 */
	public boolean inCooldown(int tick)
	{
		return lastCommitted != null && tick - lastCommitted.getTick() < lastCommitted.getSpeed();
	}

	/** @return false if the animation cannot be an attack and was dropped. */
	public boolean offer(PendingAttack attack)
	{
		if (inCooldown(attack.getTick()))
		{
			rejectedByCooldown++;
			return false;
		}

		// Two animations on one tick: the later one is what the player is actually doing.
		final PendingAttack last = pending.peekLast();
		if (last != null && last.getTick() == attack.getTick() && !last.isCommitted())
		{
			pending.pollLast();
		}

		pending.addLast(attack);
		return true;
	}

	@Nullable
	public PendingAttack matchHit(int tick, int npcIndex)
	{
		PendingAttack sameTarget = null;
		PendingAttack sameTargetSplashed = null;
		PendingAttack anyUnresolved = null;
		PendingAttack anyThisTick = null;

		for (PendingAttack a : pending)
		{
			if (!inWindow(a, tick))
			{
				continue;
			}

			final boolean open = a.getResolvedTick() < 0 || a.getResolvedTick() == tick;
			if (a.getNpcIndex() == npcIndex)
			{
				if (open)
				{
					sameTarget = a;
					break;
				}
				// Resolved by a splash is a weaker kind of open: the splash may have been
				// somebody else's, and this hit its real result. Only a fallback, so that a
				// splashed attack never takes the hit of a newer attack on the same target.
				if (a.isResolvedBySplash() && sameTargetSplashed == null)
				{
					sameTargetSplashed = a;
				}
				continue;
			}

			if (a.getResolvedTick() < 0)
			{
				if (anyUnresolved == null)
				{
					anyUnresolved = a;
				}
			}
			else if (a.getResolvedTick() == tick && anyThisTick == null)
			{
				anyThisTick = a;
			}
		}

		if (sameTarget == null)
		{
			sameTarget = sameTargetSplashed;
		}
		if (sameTarget != null)
		{
			sameTarget.setResolvedTick(tick);
			return commit(sameTarget);
		}
		if (anyUnresolved != null)
		{
			// Spill onto a secondary target does not resolve the attack; its primary hit may
			// still be in flight.
			return commit(anyUnresolved);
		}
		if (anyThisTick != null)
		{
			return commit(anyThisTick);
		}
		return null;
	}

	@Nullable
	public PendingAttack matchSplash(int tick, int npcIndex)
	{
		for (PendingAttack a : pending)
		{
			if (inWindow(a, tick) && a.isMagic() && a.getNpcIndex() == npcIndex && a.getResolvedTick() < 0)
			{
				a.setResolvedTick(tick);
				a.setResolvedBySplash(true);
				return commit(a);
			}
		}
		return null;
	}

	/**
	 * @return the tick the most recent attack on {@code npcIndex} resolved on, or -1 if none is
	 * pending or resolved. Diagnostic: tells a debug log how far a stray hitsplat landed from the
	 * attack it might have belonged to.
	 */
	public int lastResolvedTick(int npcIndex)
	{
		int last = -1;
		for (PendingAttack a : pending)
		{
			if (a.getNpcIndex() == npcIndex && a.getResolvedTick() > last)
			{
				last = a.getResolvedTick();
			}
		}
		return last;
	}

	/** @return the pending attack made on {@code tick}, if any, so a late spec-energy update can flag it. */
	@Nullable
	public PendingAttack findByTick(int tick)
	{
		for (PendingAttack a : pending)
		{
			if (a.getTick() == tick)
			{
				return a;
			}
		}
		return null;
	}

	/** Drops attacks that have fallen out of the window. @return those that never matched. */
	public List<PendingAttack> expire(int tick)
	{
		final List<PendingAttack> unmatched = new ArrayList<>();
		final Iterator<PendingAttack> it = pending.iterator();
		while (it.hasNext())
		{
			final PendingAttack a = it.next();
			if (tick - a.getTick() > windowTicks)
			{
				it.remove();
				if (!a.isCommitted())
				{
					expiredUnmatched++;
					unmatched.add(a);
				}
			}
		}
		return unmatched;
	}

	public void reset()
	{
		pending.clear();
		lastCommitted = null;
	}

	int pendingCount()
	{
		return pending.size();
	}

	private boolean inWindow(PendingAttack a, int tick)
	{
		return a.getTick() <= tick && tick - a.getTick() <= windowTicks;
	}

	private PendingAttack commit(PendingAttack attack)
	{
		if (attack.isCommitted())
		{
			return attack;
		}

		attack.setCommitted(true);
		if (lastCommitted == null || attack.getTick() >= lastCommitted.getTick())
		{
			lastCommitted = attack;
		}

		// Anything animated inside this attack's cooldown was not an attack.
		final int cooldownEnd = attack.getTick() + attack.getSpeed();
		pending.removeIf(other -> other != attack
			&& !other.isCommitted()
			&& other.getTick() > attack.getTick()
			&& other.getTick() < cooldownEnd);

		return attack;
	}
}

package com.github.ilee2.hitstats;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Works out which combat style the player's current weapon and attack-style selection deals
 * damage with, and what the selected style is called.
 *
 * <p>The style list is read out of the game's own cache the same way the client's Attack Styles
 * plugin does it, rather than from a hardcoded weapon table, so new weapon categories keep working
 * without a plugin update:
 *
 * <pre>
 *   enum 3908 : weapon category -&gt; enum of attack-style structs
 *   struct    : param 1407 -&gt; style name ("Accurate", "Ranging", "Casting", ...)
 * </pre>
 */
@Slf4j
@Singleton
class AttackStyleResolver
{
	/** Weapon category -> id of the enum listing that category's attack-style structs. */
	private static final int WEAPON_STYLES_ENUM = 3908;

	/** Struct param holding an attack style's name. */
	private static final int STYLE_NAME_PARAM = 1407;

	/**
	 * Categories missing from enum 3908; the client hardcodes these too. 22 is the bladed/staff
	 * style list (four melee styles plus the two casting slots), 30 is a plain melee list.
	 */
	private static final int CATEGORY_STAFF_FALLBACK = 22;
	private static final int CATEGORY_MELEE_FALLBACK = 30;

	private static final StyleName[] STAFF_FALLBACK_STYLES = {
		StyleName.ACCURATE, StyleName.AGGRESSIVE, null, StyleName.DEFENSIVE,
		StyleName.CASTING, StyleName.DEFENSIVE_CASTING,
	};

	private static final StyleName[] MELEE_FALLBACK_STYLES = {
		StyleName.ACCURATE, StyleName.AGGRESSIVE, StyleName.AGGRESSIVE, StyleName.DEFENSIVE,
	};

	private final Client client;

	@Getter
	private CombatStyle currentStyle = CombatStyle.UNKNOWN;

	/** Display name of the selected style, e.g. "Rapid" or "Aggressive". */
	@Getter
	private String currentStyleName = "Unknown";

	/** Whether the selected style is Rapid, which takes a tick off the weapon's attack speed. */
	@Getter
	private boolean rapid;

	@Getter
	private int weaponCategory = -1;

	@Getter
	private int styleIndex = -1;

	private int lastCastingMode = -1;

	@Inject
	AttackStyleResolver(Client client)
	{
		this.client = client;
	}

	/**
	 * Recomputes the current style from the varbits. Cheap to call every tick: the cache walk
	 * only runs when one of the three inputs actually moved.
	 */
	void update()
	{
		final int category = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		final int index = client.getVarpValue(VarPlayerID.COM_MODE);
		final int castingMode = client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);

		if (category == weaponCategory && index == styleIndex && castingMode == lastCastingMode)
		{
			return;
		}

		weaponCategory = category;
		styleIndex = index;
		lastCastingMode = castingMode;

		final StyleName style = resolve(category, index, castingMode);
		currentStyle = style == null ? CombatStyle.UNKNOWN : style.getCombatStyle();
		currentStyleName = style == null ? "Unknown" : style.getLabel();
		rapid = style == StyleName.RAPID;
	}

	void reset()
	{
		currentStyle = CombatStyle.UNKNOWN;
		currentStyleName = "Unknown";
		rapid = false;
		weaponCategory = -1;
		styleIndex = -1;
		lastCastingMode = -1;
	}

	@Nullable
	StyleName resolve(int weaponCategory, int styleIndex, int castingMode)
	{
		final StyleName[] styles = weaponTypeStyles(weaponCategory);
		if (styles == null || styles.length == 0)
		{
			return null;
		}

		// A powered staff (trident, sanguinesti, shadow, sceptres) trains Magic but its styles are
		// named Accurate/Accurate/Longrange, so the names alone would read as melee and ranged.
		// No other weapon repeats "Accurate" in the first two slots.
		if (isPoweredStaff(styles))
		{
			return StyleName.MAGIC;
		}

		// Staves put defensive casting in slot 5, selected by a separate varbit rather than by the
		// attack style varp. This mirrors the client's own script 4525.
		int index = styleIndex;
		if (index == 4)
		{
			index += castingMode;
		}

		if (index < 0 || index >= styles.length)
		{
			return null;
		}

		return styles[index];
	}

	private boolean isPoweredStaff(StyleName[] styles)
	{
		return styles.length >= 4
			&& styles[0] == StyleName.ACCURATE
			&& styles[1] == StyleName.ACCURATE
			&& styles[3] == StyleName.LONGRANGE;
	}

	@Nullable
	private StyleName[] weaponTypeStyles(int weaponCategory)
	{
		final EnumComposition categories = client.getEnum(WEAPON_STYLES_ENUM);
		if (categories == null)
		{
			return null;
		}

		final int styleEnumId = categories.getIntValue(weaponCategory);
		if (styleEnumId == -1)
		{
			switch (weaponCategory)
			{
				case CATEGORY_STAFF_FALLBACK:
					return STAFF_FALLBACK_STYLES;
				case CATEGORY_MELEE_FALLBACK:
					return MELEE_FALLBACK_STYLES;
				default:
					return null;
			}
		}

		final EnumComposition styleEnum = client.getEnum(styleEnumId);
		if (styleEnum == null)
		{
			return null;
		}

		final int[] structIds = styleEnum.getIntVals();
		final StyleName[] styles = new StyleName[structIds.length];

		int slot = 0;
		for (int structId : structIds)
		{
			final StructComposition struct = client.getStructComposition(structId);
			if (struct == null)
			{
				slot++;
				continue;
			}

			final StyleName style = StyleName.fromGameName(struct.getStringValue(STYLE_NAME_PARAM));
			if (style == null)
			{
				slot++;
				continue;
			}

			// The game reuses the "Defensive" name for the sixth slot, which is defensive casting.
			styles[slot] = slot == 5 && style == StyleName.DEFENSIVE ? StyleName.DEFENSIVE_CASTING : style;
			slot++;
		}

		return styles;
	}

	/** The style names the game stores on the attack-style structs, and what each one damages with. */
	@Getter
	enum StyleName
	{
		ACCURATE("Accurate", CombatStyle.MELEE),
		AGGRESSIVE("Aggressive", CombatStyle.MELEE),
		DEFENSIVE("Defensive", CombatStyle.MELEE),
		CONTROLLED("Controlled", CombatStyle.MELEE),
		RANGING("Accurate", CombatStyle.RANGED),
		RAPID("Rapid", CombatStyle.RANGED),
		LONGRANGE("Longrange", CombatStyle.RANGED),
		CASTING("Casting", CombatStyle.MAGIC),
		DEFENSIVE_CASTING("Defensive casting", CombatStyle.MAGIC),
		MAGIC("Magic", CombatStyle.MAGIC),
		OTHER("Other", CombatStyle.UNKNOWN),
		;

		private final String label;
		private final CombatStyle combatStyle;

		StyleName(String label, CombatStyle combatStyle)
		{
			this.label = label;
			this.combatStyle = combatStyle;
		}

		@Nullable
		static StyleName fromGameName(@Nullable String name)
		{
			if (name == null || name.isEmpty())
			{
				return null;
			}

			try
			{
				return valueOf(name.trim().toUpperCase().replace(' ', '_'));
			}
			catch (IllegalArgumentException e)
			{
				log.debug("Unrecognised attack style name '{}'", name);
				return null;
			}
		}
	}
}

package com.github.ilee2.hitstats;

import java.util.HashMap;
