import java.util.Map;
import javax.annotation.Nullable;

/**
 * Names for the values of {@code VarPlayerID.AUTOCAST_SPELL} (varp 276), which holds the
 * currently selected autocast spell. Zero means no spell is selected.
 */
final class AutocastSpell
{
	private static final Map<Integer, String> NAMES = new HashMap<>();
	private static final Map<String, Integer> IDS = new HashMap<>();

	static
	{
		put(1, "Wind Strike");
		put(2, "Water Strike");
		put(3, "Earth Strike");
		put(4, "Fire Strike");
		put(5, "Wind Bolt");
		put(6, "Water Bolt");
		put(7, "Earth Bolt");
		put(8, "Fire Bolt");
		put(9, "Wind Blast");
		put(10, "Water Blast");
		put(11, "Earth Blast");
		put(12, "Fire Blast");
		put(13, "Wind Wave");
		put(14, "Water Wave");
		put(15, "Earth Wave");
		put(16, "Fire Wave");
		put(17, "Crumble Undead");
		put(18, "Magic Dart");
		put(19, "Claws of Guthix");
		put(20, "Flames of Zamorak");
		put(31, "Smoke Rush");
		put(32, "Shadow Rush");
		put(33, "Blood Rush");
		put(34, "Ice Rush");
		put(35, "Smoke Burst");
		put(36, "Shadow Burst");
		put(37, "Blood Burst");
		put(38, "Ice Burst");
		put(39, "Smoke Blitz");
		put(40, "Shadow Blitz");
		put(41, "Blood Blitz");
		put(42, "Ice Blitz");
		put(43, "Smoke Barrage");
		put(44, "Shadow Barrage");
		put(45, "Blood Barrage");
		put(46, "Ice Barrage");
		put(47, "Iban Blast");
		put(48, "Wind Surge");
		put(49, "Water Surge");
		put(50, "Earth Surge");
		put(51, "Fire Surge");
		put(52, "Saradomin Strike");
		put(53, "Inferior Demonbane");
		put(54, "Superior Demonbane");
		put(55, "Dark Demonbane");
		put(56, "Ghostly Grasp");
		put(57, "Skeletal Grasp");
		put(58, "Undead Grasp");
	}

	private AutocastSpell()
	{
	}

	private static void put(int id, String name)
	{
		NAMES.put(id, name);
		IDS.put(normalise(name), id);
	}

	/** @return the spell's name, or a placeholder for an id this table does not know. */
	static String name(int autocastId)
	{
		final String name = NAMES.get(autocastId);
		return name != null ? name : "Spell #" + autocastId;
	}

	/** @return the autocast id for a spell name as shown in the game, or -1 if unknown. */
	static int id(@Nullable String name)
	{
		if (name == null)
		{
			return -1;
		}
		final Integer id = IDS.get(normalise(name));
		return id != null ? id : -1;
	}

	/**
	 * Whether the spell belongs to the standard spellbook. Those are the only spells a harmonised
	 * nightmare staff speeds up.
	 */
	static boolean isStandardSpellbook(int autocastId)
	{
		return (autocastId >= 1 && autocastId <= 20)
			|| autocastId == 47
			|| (autocastId >= 48 && autocastId <= 52);
	}

	private static String normalise(String name)
	{
		// The game writes "Iban's Blast"; the table stores it without the possessive.
		return name.trim().toLowerCase(Locale.ROOT).replace("iban's", "iban");
	}
}

package com.github.ilee2.hitstats;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Builder;
import lombok.Getter;

/**
 * Everything about the player and target that can move the damage distribution: worn gear,
 * levels, prayers, attack style, spell, special attack, the target NPC and the overhead prayer
 * that target was using. Two attacks made in the same context are drawn from the same
 * distribution, so hits are counted per context rather than stored one by one.
 *
 * <p>Instances are immutable; {@link #getKey()} is a stable hash of the fields and is what the
 * history file is keyed on.
 */
@Getter
public class CombatContext
{
	public static final int GEAR_SLOTS = 14;
	public static final int WEAPON_SLOT = 3;

	/** Value stored in {@link #gear} for a slot with nothing in it, and the id the gear filter
	 * uses to ask for exactly that. */
	public static final int NO_ITEM = -1;

	/**
	 * Order of the entries in {@link #boosted} and {@link #real}: the levels that can move the
	 * damage dealt. Hitpoints, Prayer and Defence are deliberately absent. The first two drift
	 * every few ticks in a fight, and keying on them turned one setup into a stream of one-attack
	 * contexts; Defence never changes the damage dealt, and an NPC that drains it split contexts
	 * for nothing.
	 */
	public static final String[] SKILL_NAMES = {"Attack", "Strength", "Ranged", "Magic"};

	/**
	 * Index of Defence in the level arrays of files written before format 6, which carried
	 * Attack, Strength, Defence, Ranged, Magic (and, before format 4, Hitpoints and Prayer after
	 * those).
	 */
	static final int LEGACY_DEFENCE_INDEX = 2;

	/** Item id per equipment slot, {@link #NO_ITEM} when empty. */
	private final int[] gear;

	/** Boosted levels, in {@link #SKILL_NAMES} order. */
	private final int[] boosted;

	/** Real (unboosted) levels, in {@link #SKILL_NAMES} order. */
	private final int[] real;

	/** Enum names of the player's active prayers, sorted. */
	private final List<String> prayers;

	private final int weaponCategory;
	private final int styleIndex;
	private final String styleName;
	private final CombatStyle combatStyle;

	/** Autocast id of the spell, -1 for a manual cast the table does not know, 0 when no spell is involved. */
	private final int spellId;

	@Nullable
	private final String spellName;

	private final boolean special;
	private final int npcId;

	/** {@link OverheadPrayer} names the target was showing when the attack was made, sorted. */
	private final List<String> targetOverheads;

	/**
	 * Whether one of {@link #targetOverheads} protects against {@link #combatStyle}. Stored rather
	 * than derived so it records what the game actually applied, even if the icon table changes.
	 */
	private final boolean styleProtected;

	/** Ticks between attacks in this context, after Rapid and spell adjustments. */
	private final int attackSpeed;

	private final String key;

	@Builder(toBuilder = true)
	public CombatContext(int[] gear, int[] boosted, int[] real, @Nullable List<String> prayers, int weaponCategory,
		int styleIndex, String styleName, CombatStyle combatStyle, int spellId, @Nullable String spellName,
		boolean special, int npcId, @Nullable List<String> targetOverheads, boolean styleProtected, int attackSpeed)
	{
		this.gear = Arrays.copyOf(gear, GEAR_SLOTS);
		this.boosted = Arrays.copyOf(boosted, SKILL_NAMES.length);
		this.real = Arrays.copyOf(real, SKILL_NAMES.length);
		this.prayers = sortedCopy(prayers);
		this.weaponCategory = weaponCategory;
		this.styleIndex = styleIndex;
		this.styleName = styleName;
		this.combatStyle = combatStyle;
		this.spellId = spellId;
		this.spellName = spellName;
		this.special = special;
		this.npcId = npcId;
		this.targetOverheads = sortedCopy(targetOverheads);
		this.styleProtected = styleProtected;
		this.attackSpeed = attackSpeed;
		this.key = computeKey();
	}

	/**
	 * Copies {@code source} with its level arrays replaced but its key kept. Only for migrating a
	 * record read from an older file: the key is what the history is stored under, and the whole
	 * point of a migration is that the record stays where it is.
	 */
	private CombatContext(CombatContext source, int[] boosted, int[] real)
	{
		this.gear = source.gear;
		this.boosted = boosted;
		this.real = real;
		this.prayers = source.prayers;
		this.weaponCategory = source.weaponCategory;
		this.styleIndex = source.styleIndex;
		this.styleName = source.styleName;
		this.combatStyle = source.combatStyle;
		this.spellId = source.spellId;
		this.spellName = source.spellName;
		this.special = source.special;
		this.npcId = source.npcId;
		this.targetOverheads = source.targetOverheads;
		this.styleProtected = source.styleProtected;
		this.attackSpeed = source.attackSpeed;
		this.key = source.key;
	}

	/**
	 * @return this context with its level arrays brought to the current {@link #SKILL_NAMES}
	 * shape, or itself if they already are. Gson fills the arrays straight from the file, so a
	 * record written when Defence was still recorded arrives with five (or seven) entries and its
	 * Ranged level sitting where the panel now expects Magic.
	 */
	CombatContext withCurrentLevelShape()
	{
		if (boosted == null || real == null
			|| (boosted.length == SKILL_NAMES.length && real.length == SKILL_NAMES.length))
		{
			return this;
		}
		return new CombatContext(this, dropLegacyDefence(boosted), dropLegacyDefence(real));
	}

	/**
	 * @return a copy of this context whose {@link #getKey() key} is computed from the fields it
	 * actually holds now. Records written before format 6 keep the key they were stored under
	 * even after {@link #withCurrentLevelShape()} has rewritten their levels, so two records
	 * that are now identical can still sit under two different keys; this is what
	 * {@code HistoryData}'s format 8 migration uses to bring them back together. It also
	 * normalises a null prayer or overhead list to an empty one, so a record from a build that
	 * predates those fields keys the same as a fresh one with neither.
	 */
	CombatContext rekeyed()
	{
		return toBuilder().build();
	}

	private static int[] dropLegacyDefence(int[] levels)
	{
		if (levels.length <= SKILL_NAMES.length)
		{
			return Arrays.copyOf(levels, SKILL_NAMES.length);
		}
		final int[] out = new int[SKILL_NAMES.length];
		int j = 0;
		for (int i = 0; i < levels.length && j < out.length; i++)
		{
			if (i != LEGACY_DEFENCE_INDEX)
			{
				out[j++] = levels[i];
			}
		}
		return out;
	}

	private static List<String> sortedCopy(@Nullable List<String> values)
	{
		if (values == null || values.isEmpty())
		{
			return Collections.emptyList();
		}
		final List<String> copy = new ArrayList<>(values);
		Collections.sort(copy);
		return Collections.unmodifiableList(copy);
	}

	/** @return a copy of this context with the special-attack flag set. */
	CombatContext asSpecial()
	{
		return toBuilder().special(true).build();
	}

	public int getWeaponId()
	{
		return gear[WEAPON_SLOT];
	}

	/**
	 * Null-safe. Gson bypasses the constructor, so a history file written before this field
	 * existed loads it as null rather than as an empty list; every reader has to tolerate that or
	 * the panel dies on the first upgrade.
	 */
	public List<String> getPrayers()
	{
		return prayers == null ? Collections.emptyList() : prayers;
	}

	/** Null-safe for the same reason as {@link #getPrayers()}. */
	public List<String> getTargetOverheads()
	{
		return targetOverheads == null ? Collections.emptyList() : targetOverheads;
	}

	/**
	 * What the attack was: the spell if one was cast, otherwise the attack style the combat tab
	 * was set to (Accurate, Aggressive, Rapid, Longrange, Casting). The damage type the game
	 * shows beside that -- Stab, Slash, Crush -- is not exposed by the client API, so it cannot
	 * be recorded without a hardcoded weapon table that would go stale.
	 */
	public String getAttackLabel()
	{
		if (spellName != null)
		{
			return spellName;
		}
		if (styleName != null && !styleName.isEmpty() && !"Unknown".equals(styleName))
		{
			return styleName;
		}
		return combatStyle.getLabel();
	}

	/** @return the target's overheads as display names, or "No overhead" when it had none. */
	public String getTargetPrayerLabel()
	{
		final List<String> overheads = getTargetOverheads();
		if (overheads.isEmpty())
		{
			return "No overhead";
		}
		final List<String> labels = new ArrayList<>(overheads.size());
		for (String name : overheads)
		{
			labels.add(OverheadPrayer.labelFor(name));
		}
		return String.join(", ", labels);
	}

	private String computeKey()
	{
		final StringBuilder sb = new StringBuilder(256);
		sb.append("g").append(Arrays.toString(gear));
		sb.append("b").append(Arrays.toString(boosted));
		sb.append("r").append(Arrays.toString(real));
		sb.append("p").append(prayers);
		sb.append("c").append(weaponCategory).append('/').append(styleIndex).append('/').append(styleName);
		sb.append("s").append(combatStyle).append('/').append(spellId).append('/').append(spellName);
		sb.append("x").append(special);
		sb.append("n").append(npcId);
		sb.append("o").append(targetOverheads).append('/').append(styleProtected);
		sb.append("a").append(attackSpeed);

		try
		{
			final MessageDigest digest = MessageDigest.getInstance("SHA-256");
			final byte[] hash = digest.digest(sb.toString().getBytes(StandardCharsets.UTF_8));
			final StringBuilder hex = new StringBuilder(32);
			for (int i = 0; i < 16; i++)
			{
				hex.append(String.format("%02x", hash[i]));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			// SHA-256 is mandatory in every JRE; fall back to something stable anyway.
			return Integer.toHexString(sb.toString().hashCode());
		}
	}
}

package com.github.ilee2.hitstats;

import lombok.Getter;

/** What an attack deals its damage with. */
@Getter
public enum CombatStyle
{
	MELEE("Melee"),
	RANGED("Ranged"),
	MAGIC("Magic"),
	UNKNOWN("Unknown");

	private final String label;

	CombatStyle(String label)
	{
		this.label = label;
	}
}

package com.github.ilee2.hitstats;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.events.GraphicChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.util.Text;

/**
 * Turns client events into store writes. Owns the {@link AttackMatcher}, the open fights, and
 * the small amount of state needed to know what the player was doing when an animation fired.
 * Everything here runs on the client thread.
 */
@Slf4j
@Singleton
class CombatTracker
{
	/** A fight with no hit or attack for this long is over, whatever happened to the NPC. */
	private static final int FIGHT_TIMEOUT_TICKS = 100;

	/** How long a clicked spell waits for the cast animation before being forgotten. */
	private static final int MANUAL_CAST_TIMEOUT_TICKS = 25;

	private static final int UNARMED_SPEED = 4;
	private static final int SPELL_SPEED = 5;
	private static final int HARMONISED_SPELL_SPEED = 4;

	/** Must stay in {@link CombatContext#SKILL_NAMES} order. */
	private static final Skill[] SKILLS = {
		Skill.ATTACK, Skill.STRENGTH, Skill.RANGED, Skill.MAGIC,
	};

	private final Client client;
	private final ItemManager itemManager;
	private final AttackStyleResolver styleResolver;
	private final HitStatsStore store;
	private final HitStatsConfig config;

	private AttackMatcher matcher;

	private final Map<Integer, Fight> fights = new HashMap<>();
	private final List<OrphanHit> orphans = new ArrayList<>();
	private final Set<Integer> splashedThisTick = new HashSet<>();
	private int splashTick = -1;

	@Nullable
	private PendingAttack lastRecorded;

	/** The NPC an animation event named this tick, held until the tick has settled. */
	@Nullable
	private NPC animatedTarget;
	private int animatedTick = -1;

	@Nullable
	private String manualSpell;
	private int manualSpellTick = -1;

	private int specEnergy = -1;
	private int specDropTick = -1;

	private int lastSaveTick;

	@Inject
	CombatTracker(Client client, ItemManager itemManager, AttackStyleResolver styleResolver,
		HitStatsStore store, HitStatsConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.styleResolver = styleResolver;
		this.store = store;
		this.config = config;
	}

	// ----------------------------------------------------------------- lifecycle

	void reset()
	{
		closeAllFights(false);
		if (matcher != null)
		{
			matcher.reset();
		}
		orphans.clear();
		splashedThisTick.clear();
		lastRecorded = null;
		animatedTarget = null;
		animatedTick = -1;
		manualSpell = null;
		specEnergy = -1;
		specDropTick = -1;
		styleResolver.reset();
	}

	/** Finishes open fights and writes the file. Called on logout and shutdown. */
	void flush()
	{
		closeAllFights(false);
		store.save();
	}

	// -------------------------------------------------------------------- events

	void onGameTick()
	{
		final int tick = client.getTickCount();
		ensureMatcher();

		if (!store.isLoaded())
		{
			final Player local = client.getLocalPlayer();
			if (local != null && local.getName() != null)
			{
				store.load(local.getName());
				lastSaveTick = tick;
			}
		}

		styleResolver.update();
		captureAttack(tick);
		retryOrphans(tick);
		closeDeadFights();
		matcher.expire(tick);
		expireFights(tick);

		if (splashTick != tick)
		{
			splashedThisTick.clear();
			splashTick = tick;
		}

		final int saveEvery = Math.max(1, config.autosaveMinutes()) * 100;
		if (tick - lastSaveTick >= saveEvery)
		{
			lastSaveTick = tick;
			store.save();
		}
	}

	void onAnimationChanged(Actor actor)
	{
		final Player local = client.getLocalPlayer();
		if (local == null || actor != local || local.getAnimation() == -1)
		{
			return;
		}

		final Actor interacting = local.getInteracting();
		if (interacting instanceof NPC)
		{
			// Only remember that it happened. The context is built at the end of the tick,
			// because the worn container and the combat-style varbits arrive as their own events
			// and an animation can be delivered before them. Snapshotting here paired the weapon
			// that had just been equipped with the style of the one before it, which is how a bow
			// ended up recorded as magic.
			animatedTarget = (NPC) interacting;
			animatedTick = client.getTickCount();
		}
	}

	/**
	 * Builds the attack for this tick, once everything the snapshot reads has settled.
	 *
	 * <p>Two ways in. Usually an animation event named the target earlier in the tick. Failing
	 * that, the player may simply be animating at an NPC: an animation held across ticks, or
	 * re-set to the id it already had, produces no event at all, and the hits from those attacks
	 * would otherwise arrive with no attack to attribute them to.
	 *
	 * <p>A false positive costs nothing: the matcher discards anything inside the previous
	 * attack's cooldown, and an attack that never matches a hitsplat or a splash is never
	 * recorded, so eating or an emote mid-fight never reaches the store.
	 */
	private void captureAttack(int tick)
	{
		if (matcher.findByTick(tick) != null)
		{
			return;
		}

		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		NPC target = null;
		boolean fromEvent = false;

		if (animatedTick == tick && animatedTarget != null)
		{
			target = animatedTarget;
			fromEvent = true;
		}
		else if (local.getAnimation() != -1 && local.getInteracting() instanceof NPC)
		{
			target = (NPC) local.getInteracting();
		}

		animatedTarget = null;

		if (target != null)
		{
			offerAttack(target, fromEvent, tick);
		}
	}

	/**
	 * @param fromEvent whether an animation event named this target. Only that path carries a
	 * manually cast spell, and only an attack the matcher accepts consumes it: a block animation
	 * from being hit while waiting for the cast to fire is also an event, and letting it take the
	 * spell left the real cast recorded under the combat tab's style, as melee.
	 */
	private void offerAttack(NPC target, boolean fromEvent, int tick)
	{
		ensureMatcher();
		if (matcher.inCooldown(tick))
		{
			// Cannot be an attack, and the matcher would say so. Checked before the snapshot
			// because a held animation lands here every tick, and the snapshot is a hash of
			// every worn item, level, prayer and the target's overhead.
			return;
		}

		final boolean special = specDropTick == tick || client.getVarpValue(VarPlayerID.SA_ATTACK) == 1;

		String spell = null;
		if (fromEvent && manualSpell != null && tick - manualSpellTick <= MANUAL_CAST_TIMEOUT_TICKS)
		{
			spell = manualSpell;
		}

		final CombatContext context = snapshot(target, special, spell);
		final PendingAttack attack = new PendingAttack(tick, target.getIndex(), context);
		if (matcher.offer(attack))
		{
			if (spell != null)
			{
				manualSpell = null;
			}
			store.rememberNpc(target);
			if (config.debugLog())
			{
				log.debug("tick {} attack on {}#{} weapon={} style={} spell={} speed={} spec={} overhead={}{}{}",
					tick, target.getName(), target.getIndex(), context.getWeaponId(), context.getStyleName(),
					context.getSpellName(), context.getAttackSpeed(), special, context.getTargetPrayerLabel(),
					context.isStyleProtected() ? " (blocks this style)" : "", fromEvent ? "" : " [no animation event]");
			}
		}
	}

	void onHitsplatApplied(HitsplatApplied event)
	{
		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		final Hitsplat hitsplat = event.getHitsplat();
		if (!hitsplat.isMine())
		{
			return;
		}

		ensureMatcher();
		final NPC npc = (NPC) event.getActor();
		final int tick = client.getTickCount();
		final boolean max = isMaxHit(hitsplat.getHitsplatType());

		if (!applyHit(tick, npc, hitsplat.getAmount(), max))
		{
			// The hitsplat can arrive in the same tick as, but ahead of, the animation. Hold it
			// until the tick has been fully processed.
			orphans.add(new OrphanHit(tick, npc, hitsplat.getAmount(), max));
		}
	}

	void onGraphicChanged(GraphicChanged event)
	{
		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		final NPC npc = (NPC) event.getActor();
		if (!npc.hasSpotAnim(SpotanimID.FAILEDSPELL_IMPACT))
		{
			return;
		}

		ensureMatcher();
		final int tick = client.getTickCount();
		if (splashTick != tick)
		{
			splashedThisTick.clear();
			splashTick = tick;
		}
		if (!splashedThisTick.add(npc.getIndex()))
		{
			return;
		}

		final PendingAttack attack = matcher.matchSplash(tick, npc.getIndex());
		if (attack == null)
		{
			// Somebody else's spell splashed on this NPC.
			return;
		}

		recordAttackIfNeeded(attack, tick);
		store.recordSplash(attack.getContext());
		final Fight fight = fightFor(npc, attack, tick);
		fight.splashes++;
		fight.lastTick = tick;

		if (config.debugLog())
		{
			log.debug("tick {} splash on {}#{} (attack tick {})", tick, npc.getName(), npc.getIndex(), attack.getTick());
		}
	}

	/**
	 * A death is noted here and acted on at the end of the tick. The killing hitsplat lands on
	 * the same tick, and nothing promises it is delivered first; closing at once would either
	 * miss it or mark the wrong hits.
	 */
	void onActorDeath(Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return;
		}
		final Fight fight = fights.get(((NPC) actor).getIndex());
		if (fight != null && fight.deathTick < 0)
		{
			fight.deathTick = client.getTickCount();
		}
	}

	void onNpcDespawned(NPC npc)
	{
		final Fight fight = fights.get(npc.getIndex());
		if (fight == null)
		{
			return;
		}
		if (npc.isDead())
		{
			if (fight.deathTick < 0)
			{
				fight.deathTick = client.getTickCount();
			}
			return;
		}
		fights.remove(npc.getIndex());
		closeFight(fight, false, client.getTickCount());
	}

	void onMenuOptionClicked(MenuOptionClicked event)
	{
		// A spell cast by hand does not change the attack style varp or the autocast varp, so the
		// only record of which spell it was is the menu entry.
		if (event.getMenuAction() != MenuAction.WIDGET_TARGET_ON_NPC || !"Cast".equals(event.getMenuOption()))
		{
			return;
		}

		final String rawTarget = event.getMenuTarget();
		if (rawTarget == null)
		{
			return;
		}
		final String target = Text.removeTags(rawTarget);
		final int arrow = target.indexOf(" -> ");
		manualSpell = arrow > 0 ? target.substring(0, arrow).trim() : target.trim();
		manualSpellTick = client.getTickCount();
	}

	void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.SA_ENERGY)
		{
			return;
		}

		// Contexts are built at the end of the tick, after every varp update in it, so noting the
		// tick is enough; the snapshot reads it.
		final int value = event.getValue();
		if (specEnergy >= 0 && value < specEnergy)
		{
			specDropTick = client.getTickCount();
		}
		specEnergy = value;
	}

	// --------------------------------------------------------------- matching

	private boolean applyHit(int tick, NPC npc, int amount, boolean max)
	{
		final PendingAttack attack = matcher.matchHit(tick, npc.getIndex());
		if (attack == null)
		{
			return false;
		}

		recordAttackIfNeeded(attack, tick);
		store.rememberNpc(npc);
		final Fight fight = fightFor(npc, attack, tick);

		if (attack.isResolvedBySplash() && attack.getNpcIndex() == npc.getIndex())
		{
			// A splash graphic carries no owner. This hitsplat is ours and came from this
			// attack, and an attack cannot both splash and hit, so the splash credited to it
			// was another player's. Take it back.
			attack.setResolvedBySplash(false);
			store.undoSplash(attack.getContext());
			if (fight.splashes > 0)
			{
				fight.splashes--;
			}
			if (config.debugLog())
			{
				log.debug("tick {} splash on {}#{} taken back: attack tick {} produced a hitsplat", tick,
					npc.getName(), npc.getIndex(), attack.getTick());
			}
		}

		store.recordHit(attack.getContext(), amount, max);
		fight.hitsplats++;
		fight.damage += amount;
		if (amount == 0)
		{
			fight.misses++;
		}
		fight.lastTick = tick;

		// Kept so the hits on the death tick can be found once the death is seen.
		if (fight.hitsTick != tick)
		{
			fight.tickHits.clear();
			fight.hitsTick = tick;
		}
		fight.tickHits.add(new TickHit(attack.getContext(), amount, max));

		if (config.debugLog())
		{
			log.debug("tick {} hit {} on {}#{} (attack tick {}{})", tick, amount, npc.getName(), npc.getIndex(),
				attack.getTick(), max ? ", max" : "");
		}
		return true;
	}

	private void retryOrphans(int tick)
	{
		final Iterator<OrphanHit> it = orphans.iterator();
		while (it.hasNext())
		{
			final OrphanHit orphan = it.next();
			// The hit's own tick, not the current one: a retry a tick later must not stamp the
			// attack, or the fight, as having resolved a tick after it did.
			if (applyHit(orphan.tick, orphan.npc, orphan.amount, orphan.max))
			{
				it.remove();
			}
			else if (tick - orphan.tick >= 1)
			{
				// Vengeance, recoil, or an animation this plugin never saw.
				it.remove();
				store.recordUnattributedHit();
				if (config.debugLog())
				{
					// How far this landed from the last attack on the same NPC. A run of these at
					// a steady one or two ticks would be a weapon whose extra hitsplats land on a
					// later tick than its first, which the matcher does not yet allow for.
					final int resolved = matcher.lastResolvedTick(orphan.npc.getIndex());
					log.debug("tick {} unattributed hit {} on {}#{}{}", orphan.tick, orphan.amount,
						orphan.npc.getName(), orphan.npc.getIndex(),
						resolved >= 0 ? " (last attack on it resolved " + (orphan.tick - resolved) + " ticks earlier)" : "");
				}
			}
		}
	}

	private void recordAttackIfNeeded(PendingAttack attack, int tick)
	{
		if (attack.isRecorded())
		{
			return;
		}
		attack.setRecorded(true);

		int wasted = 0;
		int active = attack.getSpeed();
		if (lastRecorded != null)
		{
			final int gap = attack.getTick() - lastRecorded.getTick();
			if (gap > 0 && gap <= config.idleGapTicks())
			{
				wasted = Math.max(0, gap - lastRecorded.getSpeed());
				active = gap;
			}
		}
		lastRecorded = attack;

		store.recordAttack(attack.getContext(), wasted, active);

		final Fight fight = fights.get(attack.getNpcIndex());
		if (fight != null)
		{
			fight.attacks++;
			fight.wastedTicks += wasted;
			fight.lastTick = Math.max(fight.lastTick, tick);
		}
		else
		{
			fights.put(attack.getNpcIndex(), new Fight(attack, wasted));
		}
	}

	private Fight fightFor(NPC npc, PendingAttack attack, int tick)
	{
		Fight fight = fights.get(npc.getIndex());
		if (fight == null)
		{
			// A secondary target of an area attack: the fight starts with the hit rather than
			// with an animation aimed at it.
			fight = new Fight(attack, 0);
			fight.npcId = npc.getId();
			fight.attacks = 0;
			fight.startTick = tick;
			fights.put(npc.getIndex(), fight);
		}
		return fight;
	}

	/** Closes the fights whose NPC died this tick, now that every hit of the tick has been seen. */
	private void closeDeadFights()
	{
		final Iterator<Map.Entry<Integer, Fight>> it = fights.entrySet().iterator();
		while (it.hasNext())
		{
			final Fight fight = it.next().getValue();
			if (fight.deathTick < 0)
			{
				continue;
			}
			it.remove();
			markKillingBlows(fight);
			closeFight(fight, true, fight.deathTick);
		}
	}

	/**
	 * The hits on the death tick are the killing blows. All of them: with a multi-hit weapon
	 * there is no telling which one met the cap, so the conservative reading is that any of them
	 * might have. Hits that arrive after the death, if a weapon ever does that, are simply never
	 * marked; nothing is marked by guesswork.
	 */
	private void markKillingBlows(Fight fight)
	{
		if (fight.hitsTick != fight.deathTick)
		{
			return;
		}
		for (TickHit hit : fight.tickHits)
		{
			if (hit.amount > 0)
			{
				store.markKillingBlow(hit.context, hit.amount, hit.max);
			}
		}
		if (config.debugLog())
		{
			log.debug("tick {} npc {} died: {} hit(s) on the death tick marked as killing blows",
				fight.deathTick, fight.npcId, fight.tickHits.size());
		}
	}

	private void expireFights(int tick)
	{
		final Iterator<Map.Entry<Integer, Fight>> it = fights.entrySet().iterator();
		while (it.hasNext())
		{
			final Fight fight = it.next().getValue();
			if (tick - fight.lastTick > FIGHT_TIMEOUT_TICKS)
			{
				it.remove();
				closeFight(fight, false, fight.lastTick);
			}
		}
	}

	private void closeAllFights(boolean killed)
	{
		final int tick = client.getTickCount();
		for (Fight fight : fights.values())
		{
			closeFight(fight, killed, tick);
		}
		fights.clear();
	}

	private void closeFight(Fight fight, boolean killed, int endTick)
	{
		if (fight.attacks == 0 && fight.hitsplats == 0 && fight.splashes == 0)
		{
			return;
		}

		final int duration = Math.max(1, Math.min(endTick, fight.lastTick) - fight.startTick + 1);
		store.recordFight(new KillRecord(fight.startMillis, fight.npcId, fight.contextKey, fight.weaponId,
			duration, fight.attacks, fight.hitsplats, fight.damage, fight.misses, fight.splashes,
			fight.wastedTicks, killed));

		if (config.debugLog())
		{
			log.debug("fight vs npc {} over: killed={} ticks={} attacks={} damage={}", fight.npcId, killed,
				duration, fight.attacks, fight.damage);
		}
	}

	// --------------------------------------------------------------- snapshot

	private CombatContext snapshot(NPC target, boolean special, @Nullable String manualSpell)
	{
		final int[] gear = new int[CombatContext.GEAR_SLOTS];
		Arrays.fill(gear, CombatContext.NO_ITEM);
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			for (int slot = 0; slot < CombatContext.GEAR_SLOTS; slot++)
			{
				final Item item = worn.getItem(slot);
				if (item != null && item.getId() > 0)
				{
					gear[slot] = item.getId();
					final ItemComposition composition = itemManager.getItemComposition(item.getId());
					store.rememberItem(item.getId(), composition != null ? composition.getName() : null);
				}
			}
		}

		final int[] boosted = new int[SKILLS.length];
		final int[] real = new int[SKILLS.length];
		for (int i = 0; i < SKILLS.length; i++)
		{
			boosted[i] = client.getBoostedSkillLevel(SKILLS[i]);
			real[i] = client.getRealSkillLevel(SKILLS[i]);
		}

		// Only prayers that move the damage dealt. A protection or defence prayer changes nothing
		// about our own hitsplats, and flipping one mid-fight would split the distribution in two.
		final List<String> prayers = new ArrayList<>();
		for (Prayer prayer : Prayer.values())
		{
			if (DamagePrayers.affectsDamage(prayer) && client.getVarbitValue(prayer.getVarbit()) == 1)
			{
				prayers.add(prayer.name());
			}
		}

		styleResolver.update();
		CombatStyle style = styleResolver.getCurrentStyle();
		int spellId = 0;
		String spellName = null;

		if (manualSpell != null)
		{
			style = CombatStyle.MAGIC;
			spellId = AutocastSpell.id(manualSpell);
			spellName = spellId > 0 ? AutocastSpell.name(spellId) : manualSpell;
		}
		else if (style == CombatStyle.MAGIC)
		{
			final int autocast = client.getVarbitValue(VarbitID.AUTOCAST_SPELL);
			if (autocast > 0)
			{
				spellId = autocast;
				spellName = AutocastSpell.name(autocast);
			}
		}

		final int weaponId = gear[CombatContext.WEAPON_SLOT];
		final int speed = attackSpeed(weaponId, style, spellId, spellName, styleResolver.isRapid());

		// The target's overhead at the moment of the attack. An NPC praying against the style
		// being used takes far less damage from it, so it belongs in the key rather than blending
		// two different distributions into one average.
		final Set<OverheadPrayer> overheads = OverheadPrayerReader.read(target);
		final List<String> overheadNames = new ArrayList<>(overheads.size());
		for (OverheadPrayer overhead : overheads)
		{
			overheadNames.add(overhead.name());
		}

		return CombatContext.builder()
			.gear(gear)
			.boosted(boosted)
			.real(real)
			.prayers(prayers)
			.weaponCategory(styleResolver.getWeaponCategory())
			.styleIndex(styleResolver.getStyleIndex())
			.styleName(styleResolver.getCurrentStyleName())
			.combatStyle(style)
			.spellId(spellId)
			.spellName(spellName)
			.special(special)
			.npcId(target.getId())
			.targetOverheads(overheadNames)
			.styleProtected(OverheadPrayerReader.blocks(overheads, style))
			.attackSpeed(speed)
			.build();
	}

	private int attackSpeed(int weaponId, CombatStyle style, int spellId, @Nullable String spellName, boolean rapid)
	{
		if (style == CombatStyle.MAGIC && (spellId != 0 || spellName != null))
		{
			// Spells cast at a fixed rate whatever the staff, except the harmonised nightmare
			// staff on the standard spellbook.
			if (weaponId == ItemID.NIGHTMARE_STAFF_HARMONISED && AutocastSpell.isStandardSpellbook(spellId))
			{
				return HARMONISED_SPELL_SPEED;
			}
			return SPELL_SPEED;
		}

		int speed = UNARMED_SPEED;
		if (weaponId > 0)
		{
			final ItemStats stats = itemManager.getItemStats(weaponId);
			if (stats != null && stats.getEquipment() != null && stats.getEquipment().getAspeed() > 0)
			{
				speed = stats.getEquipment().getAspeed();
			}
		}
		if (rapid)
		{
			speed = Math.max(1, speed - 1);
		}
		return speed;
	}

	private static boolean isMaxHit(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return true;
			default:
				return false;
		}
	}

	private void ensureMatcher()
	{
		final int window = Math.max(1, config.hitWindowTicks());
		if (matcher == null)
		{
			matcher = new AttackMatcher(window);
		}
		else if (matcher.getWindowTicks() != window)
		{
			// Adjust in place: rebuilding would drop the attacks still waiting for their hits.
			matcher.setWindowTicks(window);
		}
	}

	// ------------------------------------------------------------------ types

	/** An open engagement with one NPC instance. */
	private static class Fight
	{
		int npcId;
		final String contextKey;
		final int weaponId;
		final long startMillis = System.currentTimeMillis();
		int startTick;
		int lastTick;
		int attacks;
		int hitsplats;
		int damage;
		int misses;
		int splashes;
		int wastedTicks;

		/** The hits of the latest tick that produced any, and which tick that was. */
		final List<TickHit> tickHits = new ArrayList<>();
		int hitsTick = -1;

		/** The tick the death was seen on, or -1. The fight closes at the end of that tick. */
		int deathTick = -1;

		Fight(PendingAttack first, int wasted)
		{
			this.npcId = first.getContext().getNpcId();
			this.contextKey = first.getContext().getKey();
			this.weaponId = first.getContext().getWeaponId();
			this.startTick = first.getTick();
			this.lastTick = first.getTick();
			this.attacks = 1;
			this.wastedTicks = wasted;
		}
	}

	/** A hit already written to the store, remembered until the tick ends in case it was the kill. */
	private static class TickHit
	{
		final CombatContext context;
		final int amount;
		final boolean max;

		TickHit(CombatContext context, int amount, boolean max)
		{
			this.context = context;
			this.amount = amount;
			this.max = max;
		}
	}

	/** A hitsplat of ours that arrived before its attack animation. */
	private static class OrphanHit
	{
		final int tick;
		final NPC npc;
		final int amount;
		final boolean max;

		OrphanHit(int tick, NPC npc, int amount, boolean max)
		{
			this.tick = tick;
			this.npc = npc;
			this.amount = amount;
			this.max = max;
		}
	}
}

package com.github.ilee2.hitstats;

import java.util.Arrays;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * Everything recorded for one {@link CombatContext}: a histogram of hitsplat amounts plus the
 * counters the summary statistics derive from. Index 0 of the histogram is a miss (a 0 hitsplat);
 * splashes produce no hitsplat and are counted separately.
 *
 * <p>Killing blows live in a histogram of their own. The hit that kills a monster is capped by
 * its remaining hitpoints, so it is not a fair sample of what the weapon rolls; the panel can
 * chart the distribution with or without them. The death is only seen after the hit, so a hit is
 * counted in {@link #counts} first and moved by {@link #markKillingBlow} a moment later.
 */
@Getter
public class ContextStats
{
	private static final int[] NO_COUNTS = new int[0];

	private CombatContext context;

	/** {@code counts[d]} is how many hitsplats of {@code d} damage were seen, killing blows aside. */
	private int[] counts = new int[1];

	/**
	 * {@code killCounts[d]} is how many hitsplats of {@code d} damage ended a fight. Null in
	 * files from before format 7, whose killing blows are still in {@link #counts} and cannot be
	 * told apart after the fact.
	 */
	@Nullable
	private int[] killCounts;

	/** Attacks committed in this context (an attack may produce several hitsplats). */
	private int attacks;

	/** Hitsplats recorded, including zeros and killing blows. */
	private int hitsplats;

	private int splashes;

	/** Hitsplats the game flagged as a max hit, killing blows included. */
	private int maxHits;

	/** How many hitsplats are in {@link #killCounts}. */
	private int killingBlows;

	/** How many of the killing blows the game flagged as a max hit. */
	private int killingBlowMaxHits;

	/** Ticks the player could have attacked on but did not. */
	private int wastedTicks;

	/** Ticks spent in combat, for DPS. */
	private int activeTicks;

	private long firstSeen;
	private long lastSeen;

	ContextStats()
	{
		// For Gson.
	}

	ContextStats(CombatContext context)
	{
		this.context = context;
		this.firstSeen = System.currentTimeMillis();
		this.lastSeen = firstSeen;
	}

	/** Deep copy, so the Swing thread can read a snapshot while the client thread keeps writing. */
	ContextStats copy()
	{
		final ContextStats c = new ContextStats();
		c.context = context;
		c.counts = Arrays.copyOf(counts, counts.length);
		c.killCounts = killCounts == null ? null : Arrays.copyOf(killCounts, killCounts.length);
		c.attacks = attacks;
		c.hitsplats = hitsplats;
		c.splashes = splashes;
		c.maxHits = maxHits;
		c.killingBlows = killingBlows;
		c.killingBlowMaxHits = killingBlowMaxHits;
		c.wastedTicks = wastedTicks;
		c.activeTicks = activeTicks;
		c.firstSeen = firstSeen;
		c.lastSeen = lastSeen;
		return c;
	}

	/** Brings a record read from an older file up to the current context shape. Keeps the key. */
	void migrate()
	{
		if (context != null)
		{
			context = context.withCurrentLevelShape();
		}
	}

	/** Replaces the context, and with it the key this record belongs under. See format 8. */
	void rekey(CombatContext replacement)
	{
		context = replacement;
	}

	/**
	 * Folds {@code other} into this record. Every counter here describes the same setup under the
	 * same key, so all of them are additive: histograms sum index by index, totals sum, and the
	 * window widens to cover both. Used by the format 8 migration, where several records written
	 * under stale keys turn out to describe one setup.
	 */
	void mergeFrom(ContextStats other)
	{
		counts = sum(counts, other.counts);
		killCounts = sum(killCounts, other.killCounts);
		attacks += other.attacks;
		hitsplats += other.hitsplats;
		splashes += other.splashes;
		maxHits += other.maxHits;
		killingBlows += other.killingBlows;
		killingBlowMaxHits += other.killingBlowMaxHits;
		wastedTicks += other.wastedTicks;
		activeTicks += other.activeTicks;
		firstSeen = earliest(firstSeen, other.firstSeen);
		lastSeen = Math.max(lastSeen, other.lastSeen);
	}

	/**
	 * @return {@code a} and {@code b} added index by index, at the length of the longer. Null is
	 * an empty histogram, and stays null when both sides are empty so a record that never had a
	 * killing blow does not gain an array by being merged.
	 */
	@Nullable
	private static int[] sum(@Nullable int[] a, @Nullable int[] b)
	{
		if (a == null || a.length == 0)
		{
			return b == null ? a : Arrays.copyOf(b, b.length);
		}
		if (b == null || b.length == 0)
		{
			return a;
		}

		final int[] out = Arrays.copyOf(a, Math.max(a.length, b.length));
		for (int i = 0; i < b.length; i++)
		{
			out[i] += b[i];
		}
		return out;
	}

	/** Zero means "never recorded", not "1970", so it must not win a minimum. */
	private static long earliest(long a, long b)
	{
		if (a <= 0)
		{
			return b;
		}
		if (b <= 0)
		{
			return a;
		}
		return Math.min(a, b);
	}

	/** Never null, whatever the file said. */
	public int[] getKillCounts()
	{
		return killCounts == null ? NO_COUNTS : killCounts;
	}

	void recordAttack(int wasted, int active)
	{
		attacks++;
		wastedTicks += wasted;
		activeTicks += active;
		touch();
	}

	void recordHit(int amount, boolean max)
	{
		if (amount < 0)
		{
			amount = 0;
		}
		if (amount >= counts.length)
		{
			counts = Arrays.copyOf(counts, amount + 1);
		}
		counts[amount]++;
		hitsplats++;
		if (max)
		{
			maxHits++;
		}
		touch();
	}

	/**
	 * Moves one hitsplat of {@code amount} out of the histogram and into the killing blows. The
	 * hitsplat and max-hit totals are untouched: they count every hit, and the killing-blow
	 * counters say how many of them ended a fight.
	 *
	 * @return false if the histogram holds no such hitsplat, in which case nothing changes.
	 */
	boolean markKillingBlow(int amount, boolean max)
	{
		if (amount <= 0 || amount >= counts.length || counts[amount] == 0)
		{
			return false;
		}

		counts[amount]--;
		if (killCounts == null)
		{
			killCounts = new int[amount + 1];
		}
		else if (amount >= killCounts.length)
		{
			killCounts = Arrays.copyOf(killCounts, amount + 1);
		}
		killCounts[amount]++;
		killingBlows++;
		if (max)
		{
			killingBlowMaxHits++;
		}
		touch();
		return true;
	}

	void recordSplash()
	{
		splashes++;
		touch();
	}

	/** Takes back a splash that turned out to be someone else's; see the tracker. */
	void undoSplash()
	{
		if (splashes > 0)
		{
			splashes--;
			touch();
		}
	}

	private void touch()
	{
		lastSeen = System.currentTimeMillis();
	}

	/** Every point of damage dealt in this context, killing blows included. */
	public int getTotalDamage()
	{
		return damageIn(counts) + getKillingBlowDamage();
	}

	public int getKillingBlowDamage()
	{
		return damageIn(getKillCounts());
	}

	private static int damageIn(int[] histogram)
	{
		int total = 0;
		for (int d = 1; d < histogram.length; d++)
		{
			total += d * histogram[d];
		}
		return total;
	}

	public int getZeroHits()
	{
		return counts.length > 0 ? counts[0] : 0;
	}

	/** The highest hit in the distribution proper; a capped killing blow cannot beat it. */
	public int getHighestHit()
	{
		for (int d = counts.length - 1; d > 0; d--)
		{
			if (counts[d] > 0)
			{
				return d;
			}
		}
		return 0;
	}
}

package com.github.ilee2.hitstats;

import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.Prayer;

/**
 * Which prayers belong in a {@link CombatContext}.
 *
 * <p>Only prayers that change the damage you deal matter here. Protection prayers, defence
 * prayers and the restore/utility ones change nothing about your own hitsplats, and flipping them
 * mid-fight would otherwise split one distribution into several for no reason.
 *
 * <p>The list below is what is <em>excluded</em>, not what is included, so a prayer this plugin
 * has never heard of is kept rather than silently merged into someone else's distribution. Being
 * wrong in that direction only costs an extra row in the breakdown; being wrong the other way
 * blends two genuinely different distributions into one misleading average.
 */
final class DamagePrayers
{
	private static final Set<Prayer> NO_EFFECT_ON_DAMAGE_DEALT = EnumSet.of(
		// Defence only.
		Prayer.THICK_SKIN,
		Prayer.ROCK_SKIN,
		Prayer.STEEL_SKIN,

		// Overhead protection: changes what you take, not what you deal.
		Prayer.PROTECT_FROM_MAGIC,
		Prayer.PROTECT_FROM_MISSILES,
		Prayer.PROTECT_FROM_MELEE,

		// Restore and utility.
		Prayer.RAPID_RESTORE,
		Prayer.RAPID_HEAL,
		Prayer.PRESERVE,
		Prayer.PROTECT_ITEM,

		// Effects that fire on damage taken or on death, not on the attacks you make.
		Prayer.RETRIBUTION,
		Prayer.REDEMPTION,
		Prayer.SMITE,

		// Ruinous equivalents of the above.
		Prayer.RP_REJUVENATION,
		Prayer.RP_PROTECT_ITEM,
		Prayer.RP_RUINOUS_GRACE,
		Prayer.RP_DAMPEN_MAGIC,
		Prayer.RP_DAMPEN_RANGED,
		Prayer.RP_DAMPEN_MELEE);

	private DamagePrayers()
	{
	}

	/**
	 * @return whether this prayer can move the damage you deal, through accuracy or through
	 * damage itself. Accuracy counts: it changes how often a zero is rolled, which is the shape
	 * of the distribution.
	 */
	static boolean affectsDamage(Prayer prayer)
	{
		return !NO_EFFECT_ON_DAMAGE_DEALT.contains(prayer);
	}

	/** @return how many prayers are deliberately left out of the context. */
	static int ignoredCount()
	{
		return NO_EFFECT_ON_DAMAGE_DEALT.size();
	}
}

