package com.github.ilee2.hitstats;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Getter;

/** Root of the history file for one player. */
@Getter
public class HistoryData
{
	/**
	 * 1: initial format.
	 * 2: contexts carry the target's overhead prayers and whether they blocked the style used.
	 * 3: only prayers that affect the damage dealt are recorded, so protection and defence
	 * prayers no longer split a distribution.
	 * 4: Hitpoints and Prayer levels are no longer recorded, for the same reason: they drift
	 * constantly in a fight and cannot change the damage dealt.
	 * 5: a capped log of individual hits sits alongside the aggregates.
	 * 6: Defence is no longer recorded either; it cannot change the damage dealt. Older records
	 * have it dropped from their level arrays on load so the panel reads them correctly.
	 * 7: the hit that kills a monster is moved into a killing-blow histogram of its own once the
	 * death is seen, and flagged in the hit log, so the panel can chart the distribution without
	 * hits that were capped by the monster's remaining hitpoints. Records from older files keep
	 * their killing blows in the main histogram; they cannot be told apart after the fact.
	 * 8: every record's key is recomputed from the fields it actually holds, and records that
	 * land on the same key are merged. Versions 3, 4 and 6 each removed something from the key
	 * but left existing records under the key they were written with, so a setup recorded before
	 * one of those changes sat in its own frozen record and never received another hit. One real
	 * file held 983 records that were 140 setups. See {@link #mergeStaleKeys()}.
	 */
	public static final int CURRENT_VERSION = 8;

	/** The first version whose keys are computed the way {@link CombatContext} computes them now. */
	private static final int FIRST_STABLE_KEY_VERSION = 8;

	private int version = CURRENT_VERSION;
	private Map<Integer, NpcName> npcNames = new HashMap<>();
	private Map<Integer, String> itemNames = new HashMap<>();
	private Map<String, ContextStats> contexts = new HashMap<>();
	private List<KillRecord> fights = new ArrayList<>();

	/** The most recent hits, oldest first, capped so the file cannot grow without bound. */
	private List<HitRecord> recentHits = new ArrayList<>();

	/** Own hitsplats that arrived with no attack to hang them on; a diagnostic, never charted. */
	private int unattributedHits;

	/**
	 * Random id identifying this file to the community server, created the first time an upload
	 * is attempted and never derived from anything about the account. Null in every file written
	 * before the upload existed, and in one that has never opted in. Clearing the history throws
	 * the whole {@code HistoryData} away, so a cleared history becomes a new uploader and the
	 * rows already on the server are left alone; that is the right behaviour for counters that
	 * have just gone back to zero.
	 */
	@Nullable
	private String uploaderId;

	/**
	 * The largest {@link ContextStats#getLastSeen()} the server has acknowledged. Everything
	 * touched since is what the next upload sends.
	 */
	private long uploadedThrough;

	void setUploaderId(String id)
	{
		uploaderId = id;
	}

	void setUploadedThrough(long through)
	{
		uploadedThrough = through;
	}

	void incrementUnattributed()
	{
		unattributedHits++;
	}

	/**
	 * Brings a file read from an older version up to date. Nothing is ever discarded: a record
	 * either stays where it is or is added into the record it turns out to be a duplicate of.
	 */
	void upgrade()
	{
		if (version < 6)
		{
			for (ContextStats stats : contexts.values())
			{
				stats.migrate();
			}
		}
		if (version < FIRST_STABLE_KEY_VERSION)
		{
			mergeStaleKeys();
		}
		version = CURRENT_VERSION;
	}

	/**
	 * Recomputes every record's key from the fields it holds and folds together the records that
	 * agree. Two records can only collide here if every field in the key matches, which means
	 * they describe the same setup and their counters are the same measurement taken twice; every
	 * counter is additive, so merging them loses nothing.
	 *
	 * <p>Fights and logged hits point at a context by key, so they are moved with the records
	 * they belong to. Missing that leaves them pointing at keys nothing answers to.
	 */
	private void mergeStaleKeys()
	{
		final Map<String, ContextStats> merged = new HashMap<>(contexts.size());
		final Map<String, String> moved = new HashMap<>();

		for (Map.Entry<String, ContextStats> entry : contexts.entrySet())
		{
			final ContextStats stats = entry.getValue();
			if (stats == null || stats.getContext() == null)
			{
				continue;
			}

			final CombatContext rekeyed = stats.getContext().rekeyed();
			final String key = rekeyed.getKey();
			if (!key.equals(entry.getKey()))
			{
				moved.put(entry.getKey(), key);
			}

			final ContextStats existing = merged.get(key);
			if (existing == null)
			{
				stats.rekey(rekeyed);
				merged.put(key, stats);
			}
			else
			{
				existing.mergeFrom(stats);
			}
		}

		contexts = merged;

		if (moved.isEmpty())
		{
			return;
		}
		for (KillRecord fight : fights)
		{
			fight.remapContext(moved);
		}
		for (HitRecord hit : recentHits)
		{
			hit.remapContext(moved);
		}
	}
}

package com.github.ilee2.hitstats;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Getter;

/** Which contexts and fights to fold into an {@link Aggregate}. A null or absent field means "any". */
@Getter
public class HistoryFilter
{
	public static final HistoryFilter ALL = new HistoryFilter(null, null, null, null, null);

	/** NPC display name, matched via the store's id-to-name map. */
	@Nullable
	private final String npcName;

	/** Exact NPC id, for when phases or forms of one name are being split apart. */
	@Nullable
	private final Integer npcId;

	/**
	 * Equipment slot index to the item id required in it. A slot that is absent is not filtered
	 * on. Every worn slot moves the damage distribution, so all of them can be filtered, and the
	 * weapon is simply slot {@link CombatContext#WEAPON_SLOT} rather than a field of its own.
	 */
	private final Map<Integer, Integer> gear;

	/** {@link CombatContext#getAttackLabel()} value, e.g. "Melee" or "Ice Barrage". */
	@Nullable
	private final String attackLabel;

	/**
	 * Whether the target was praying against the style used. TRUE keeps only protected attacks,
	 * FALSE only unprotected ones, null keeps both.
	 */
	@Nullable
	private final Boolean styleProtected;

	public HistoryFilter(@Nullable String npcName, @Nullable Integer npcId,
		@Nullable Map<Integer, Integer> gear, @Nullable String attackLabel, @Nullable Boolean styleProtected)
	{
		this.npcName = npcName;
		this.npcId = npcId;
		this.gear = gear == null || gear.isEmpty()
			? Collections.emptyMap()
			: Collections.unmodifiableMap(new HashMap<>(gear));
		this.attackLabel = attackLabel;
		this.styleProtected = styleProtected;
	}

	/** Convenience for the weapon slot, which is the one most things care about. */
	@Nullable
	public Integer getWeaponId()
	{
		return gear.get(CombatContext.WEAPON_SLOT);
	}

	/** @return this filter with the monster dimension dropped. */
	HistoryFilter withoutNpc()
	{
		return new HistoryFilter(null, null, gear, attackLabel, styleProtected);
	}

	/** @return this filter with the attack dimension dropped. */
	HistoryFilter withoutAttack()
	{
		return new HistoryFilter(npcName, npcId, gear, null, styleProtected);
	}

	/** @return this filter with the target-protection dimension dropped. */
	public HistoryFilter withoutProtection()
	{
		return styleProtected == null
			? this
			: new HistoryFilter(npcName, npcId, gear, attackLabel, null);
	}

	/** @return this filter with one equipment slot dropped. */
	HistoryFilter withoutSlot(int slot)
	{
		if (!gear.containsKey(slot))
		{
			return this;
		}
		final Map<Integer, Integer> without = new HashMap<>(gear);
		without.remove(slot);
		return new HistoryFilter(npcName, npcId, without, attackLabel, styleProtected);
	}
}

package com.github.ilee2.hitstats;

/**
 * Which body of records a panel view is built from, narrowest first.
 *
 * <p>{@link #ALL_TIME} is everything in the character's history file. {@link #SESSION} is only
 * what has been recorded since that character logged in. {@link #CURRENT_FIGHT} is everything
 * since the first attack after the last kill: at a boss that is the fight in progress, and once
 * the boss dies it stays on screen until the next fight starts, so a kill can be read after the
 * fact. In multi-way combat it is "since the last thing died", which is the honest reading.
 *
 * <p>Only the all-time records are written to disk. The other two are held in memory and end
 * with the client.
 */
public enum HistoryScope
{
	CURRENT_FIGHT("Current fight"),
	SESSION("This session"),
	ALL_TIME("All time");

	private final String label;

	HistoryScope(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.github.ilee2.hitstats;

import java.util.Map;
import lombok.Getter;
import lombok.NoArgsConstructor;

/**
 * One hitsplat, kept so the panel can list what actually happened rather than only the shape of
 * it. The aggregates are what the statistics are built from; this is the log beside them.
 *
 * <p>Only the most recent few hundred are kept, so the file stays small however long the history
 * runs. {@link #contextKey} points back at the full setup, which is stored once per setup rather
 * than once per hit.
 */
@Getter
@NoArgsConstructor
public class HitRecord
{
	/** Damage value standing for a splash, which produces no hitsplat at all. */
	public static final int SPLASH = -1;

	private long timestamp;
	private int npcId;
	private int weaponId;

	/** Damage dealt, 0 for a miss, or {@link #SPLASH}. */
	private int damage;

	/** Whether the game flagged this as a max hit. */
	private boolean max;

	private String contextKey;

	/**
	 * Whether this hit ended the fight. The death is only seen after the hit, so a record is
	 * written without this and flagged a moment later. Files from before format 7 never carry
	 * it, and read as false.
	 */
	private boolean killingBlow;

	public HitRecord(long timestamp, int npcId, int weaponId, int damage, boolean max, String contextKey)
	{
		this.timestamp = timestamp;
		this.npcId = npcId;
		this.weaponId = weaponId;
		this.damage = damage;
		this.max = max;
		this.contextKey = contextKey;
	}

	public boolean isSplash()
	{
		return damage == SPLASH;
	}

	void markKillingBlow()
	{
		killingBlow = true;
	}

	/** Points this hit at the key its context now lives under; see {@code KillRecord.remapContext}. */
	void remapContext(Map<String, String> newKeys)
	{
		final String moved = newKeys.get(contextKey);
		if (moved != null)
		{
			contextKey = moved;
		}
	}
}

