package com.github.ilee2.hitstats;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * The overhead prayer icons an NPC can display, and which combat styles each one protects
 * against. An NPC praying against the style you are using takes far less damage from it, so this
 * is part of the recorded context.
 *
 * <p>Ordinals are the sprite indexes inside the game's overhead-prayer sprite archive, which is
 * also the ordering of {@link net.runelite.api.HeadIcon} (that enum is only exposed for players --
 * NPCs hand out raw archive/sprite id pairs, see {@link OverheadPrayerReader}).
 */
@Getter
public enum OverheadPrayer
{
	PROTECT_FROM_MELEE("Protect from Melee", CombatStyle.MELEE),
	PROTECT_FROM_MISSILES("Protect from Missiles", CombatStyle.RANGED),
	PROTECT_FROM_MAGIC("Protect from Magic", CombatStyle.MAGIC),
	RETRIBUTION("Retribution"),
	SMITE("Smite"),
	REDEMPTION("Redemption"),
	PROTECT_RANGE_MAGE("Protect from Missiles + Magic", CombatStyle.RANGED, CombatStyle.MAGIC),
	PROTECT_RANGE_MELEE("Protect from Missiles + Melee", CombatStyle.RANGED, CombatStyle.MELEE),
	PROTECT_MAGE_MELEE("Protect from Magic + Melee", CombatStyle.MAGIC, CombatStyle.MELEE),
	PROTECT_ALL("Protect from All", CombatStyle.RANGED, CombatStyle.MAGIC, CombatStyle.MELEE),
	WRATH("Wrath"),
	SOUL_SPLIT("Soul Split"),
	DEFLECT_MELEE("Deflect Melee", CombatStyle.MELEE),
	DEFLECT_MISSILES("Deflect Missiles", CombatStyle.RANGED),
	DEFLECT_MAGIC("Deflect Magic", CombatStyle.MAGIC),
	;

	private static final OverheadPrayer[] VALUES = values();

	private final String label;
	private final Set<CombatStyle> blockedStyles;

	OverheadPrayer(String label, CombatStyle... blockedStyles)
	{
		this.label = label;
		this.blockedStyles = blockedStyles.length == 0
			? Collections.emptySet()
			: Collections.unmodifiableSet(EnumSet.of(blockedStyles[0], blockedStyles));
	}

	/**
	 * @return the prayer at the given sprite index, or null if the index is outside the archive
	 * (a game update adding new icons lands here, and is treated as "no protection" rather than
	 * guessed at).
	 */
	@Nullable
	static OverheadPrayer forSpriteIndex(int spriteIndex)
	{
		return spriteIndex >= 0 && spriteIndex < VALUES.length ? VALUES[spriteIndex] : null;
	}

	/** @return the display name for a stored enum name, or the raw value if it is unrecognised. */
	static String labelFor(String enumName)
	{
		try
		{
			return valueOf(enumName).getLabel();
		}
		catch (IllegalArgumentException e)
		{
			return enumName;
		}
	}

	public boolean blocks(CombatStyle style)
	{
		return blockedStyles.contains(style);
	}

	public boolean isProtective()
	{
		return !blockedStyles.isEmpty();
	}
}

package com.github.ilee2.hitstats;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;

/**
 * Reads the overhead prayer icons currently drawn above an NPC.
 *
 * <p>{@link net.runelite.api.HeadIcon} is only available for players. An NPC exposes its overheads
 * as parallel arrays of sprite archive ids and sprite indexes ({@link NPC#getOverheadArchiveIds()}
 * / {@link NPC#getOverheadSpriteIds()}), which is what lets a single NPC show more than one icon at
 * a time.
 */
@Slf4j
final class OverheadPrayerReader
{
	/**
	 * Sprite archive holding the overhead prayer icons. It is the archive
	 * {@code SpriteID.OVERHEAD_PROTECT_FROM_MELEE} names -- the old flat SpriteID table had one
	 * constant per archive, named after the archive's first sprite.
	 */
	private static final int PRAYER_HEADICON_ARCHIVE = 440;

	/** Some NPCs leave the archive unset, meaning "the default prayer archive". */
	private static final int DEFAULT_ARCHIVE = -1;

	private OverheadPrayerReader()
	{
	}

	/**
	 * @return every overhead prayer icon above {@code npc}, in the order the game draws them.
	 * Empty when the NPC has no overhead, or when its overheads come from an archive this plugin
	 * does not recognise (custom boss icons), which is reported as "no protection" rather than
	 * guessed at.
	 */
	static Set<OverheadPrayer> read(NPC npc)
	{
		final short[] spriteIds = npc.getOverheadSpriteIds();
		if (spriteIds == null || spriteIds.length == 0)
		{
			return Collections.emptySet();
		}

		final int[] archiveIds = npc.getOverheadArchiveIds();

		// LinkedHashSet, not EnumSet: draw order is worth keeping for the readout.
		final Set<OverheadPrayer> prayers = new LinkedHashSet<>(spriteIds.length);
		for (int i = 0; i < spriteIds.length; i++)
		{
			final int archive = archiveIds != null && i < archiveIds.length ? archiveIds[i] : DEFAULT_ARCHIVE;
			if (archive != PRAYER_HEADICON_ARCHIVE && archive != DEFAULT_ARCHIVE)
			{
				log.debug("Ignoring overhead icon from unknown archive {} on npc {}", archive, npc.getId());
				continue;
			}

			final OverheadPrayer prayer = OverheadPrayer.forSpriteIndex(spriteIds[i]);
			if (prayer == null)
			{
				log.debug("Unknown overhead sprite index {} on npc {}", spriteIds[i], npc.getId());
				continue;
			}

			prayers.add(prayer);
		}

		return prayers;
	}

	/** @return whether any of {@code prayers} protects against {@code style}. */
	static boolean blocks(Set<OverheadPrayer> prayers, CombatStyle style)
	{
		if (style == CombatStyle.UNKNOWN)
		{
			return false;
		}
		for (OverheadPrayer prayer : prayers)
		{
			if (prayer.blocks(style))
			{
				return true;
			}
		}
		return false;
	}
}

package com.github.ilee2.hitstats;

import lombok.Getter;
import lombok.Setter;

/**
 * An attack animation seen on the player, waiting for its hitsplat or splash. Snapshotting the
 * context here rather than when the hit lands is what keeps a gear switch during a projectile's
 * flight from crediting the wrong weapon.
 */
@Getter
public class PendingAttack
{
	private final int tick;
	private final int npcIndex;
	private final CombatContext context;

	/** Set once a hitsplat or splash has been matched to this attack. */
	@Setter
	private boolean committed;

	/** Tick the primary target's hit or splash landed on, or -1 while still waiting. */
	@Setter
	private int resolvedTick = -1;

	/**
	 * Set when what resolved this attack was a splash graphic rather than a hitsplat. A splash
	 * carries no owner, so a hit of ours on the same target arriving afterwards means the splash
	 * was another player's; the tracker clears this once it has taken the splash back.
	 */
	@Setter
	private boolean resolvedBySplash;

	/** Set by the tracker once the attack has been counted in the store. */
	@Setter
	private boolean recorded;

	public PendingAttack(int tick, int npcIndex, CombatContext context)
	{
		this.tick = tick;
		this.npcIndex = npcIndex;
		this.context = context;
	}

	int getSpeed()
	{
		return context.getAttackSpeed();
	}

	boolean isMagic()
	{
		return context.getCombatStyle() == CombatStyle.MAGIC;
	}
}

package com.github.ilee2.hitstats.sync;

import java.util.Arrays;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * What everyone else's hits look like for one filter, as the server returned it.
 *
 * <p>The line is everyone who has shared data for this setup, the reader included when they have
 * shared any: subtracting the reader's own rows from a total that was summed before their last
 * upload can go negative, and the count of other players says all the panel needs to say.
 *
 * <p>Fields are the wire format, so Gson fills them directly. Everything derived is computed the
 * same way {@code Aggregate} computes it locally, or the two halves of the comparison would not
 * mean the same thing.
 */
@Getter
public class CommunityAggregate
{
	private static final double SECONDS_PER_TICK = 0.6;
	private static final int[] NO_COUNTS = new int[0];

	private boolean ok;

	/** Everyone in the sample, the reader included. */
	private int players;

	/** Everyone but the reader. What the panel shows. */
	private int others;

	private boolean includesYou;

	/** How many recorded setups were folded in; a rough measure of how broad the filter was. */
	private int buckets;

	/** Nobody has shared anything matching this filter yet. */
	private boolean empty;

	/** The filter matched more than the server will aggregate in one go. */
	private boolean tooBroad;

	@Nullable
	private int[] counts;

	@Nullable
	private int[] killCounts;

	private int attacks;
	private int hitsplats;
	private int splashes;
	private int maxHits;
	private int killingBlows;
	private int killingBlowMaxHits;
	private int wastedTicks;
	private int activeTicks;

	@Nullable
	private Epoch epoch;

	private long rebuiltAt;

	/**
	 * Whether the killing blows belong in the distribution. Not from the server: it is the panel's
	 * own toggle, and both halves of the comparison have to answer it the same way or the averages
	 * mean different things. The server always sends the two histograms apart.
	 */
	private transient boolean includeKillingBlows = true;

	public void setIncludeKillingBlows(boolean include)
	{
		includeKillingBlows = include;
	}

	/** Hitsplats by damage with the killing blows left out; what the server stores. */
	public int[] getCounts()
	{
		return counts == null ? NO_COUNTS : counts;
	}

	/**
	 * The histogram as charted, which is what every shape statistic below is built from: the
	 * hitsplats, with the killing blows folded back in when they are being counted. A killing blow
	 * is capped by the monster's remaining hitpoints, so leaving it out is what shows the weapon's
	 * real roll.
	 */
	public int[] getChartedCounts()
	{
		final int[] hits = getCounts();
		if (!includeKillingBlows)
		{
			return hits;
		}

		final int[] kills = getKillCounts();
		if (kills.length == 0)
		{
			return hits;
		}

		final int[] out = Arrays.copyOf(hits, Math.max(hits.length, kills.length));
		for (int d = 0; d < kills.length; d++)
		{
			out[d] += kills[d];
		}
		return out;
	}

	public int getChartedHitsplats()
	{
		return includeKillingBlows ? hitsplats : hitsplats - killingBlows;
	}

	/** Max hits among the charted hitsplats, to match how the local side counts them. */
	public int getChartedMaxHits()
	{
		return includeKillingBlows ? maxHits : maxHits - killingBlowMaxHits;
	}

	public int[] getKillCounts()
	{
		return killCounts == null ? NO_COUNTS : killCounts;
	}

	/** Whether there is a distribution worth drawing. */
	public boolean hasData()
	{
		return ok && !empty && !tooBroad && hitsplats > 0;
	}

	/**
	 * Every point of damage dealt, killing blows included whether or not they are charted. Damage
	 * done is damage done; only the shape statistics follow the toggle.
	 */
	public int getTotalDamage()
	{
		return damageIn(getCounts()) + damageIn(getKillCounts());
	}

	/** The damage in the charted histogram, which is what the averages divide. */
	public int getChartedDamage()
	{
		return damageIn(getChartedCounts());
	}

	public int getZeroHits()
	{
		final int[] c = getCounts();
		return c.length > 0 ? c[0] : 0;
	}

	public int getLandedHits()
	{
		return hitsplats - getZeroHits();
	}

	/** Hitsplats plus splashes: everything that was an attempt to land a hit. */
	public int getAttempts()
	{
		return hitsplats + splashes;
	}

	public double getAveragePerHitsplat()
	{
		final int charted = getChartedHitsplats();
		return charted == 0 ? 0 : (double) getChartedDamage() / charted;
	}

	public double getAveragePerLandedHit()
	{
		final int landed = getLandedHits();
		return landed == 0 ? 0 : (double) getTotalDamage() / landed;
	}

	public double getAccuracy()
	{
		final int attempts = getAttempts();
		return attempts == 0 ? 0 : (double) getLandedHits() / attempts;
	}

	public double getSplashRate()
	{
		final int attempts = getAttempts();
		return attempts == 0 ? 0 : (double) splashes / attempts;
	}

	public double getMaxHitRate()
	{
		final int charted = getChartedHitsplats();
		return charted == 0 ? 0 : (double) getChartedMaxHits() / charted;
	}

	public double getDps()
	{
		return activeTicks == 0 ? 0 : getTotalDamage() / (activeTicks * SECONDS_PER_TICK);
	}

	public double getWastedPerAttack()
	{
		return attacks == 0 ? 0 : (double) wastedTicks / attacks;
	}

	public int getHighestHit()
	{
		final int[] c = getChartedCounts();
		for (int d = c.length - 1; d > 0; d--)
		{
			if (c[d] > 0)
			{
				return d;
			}
		}
		return 0;
	}

	private static int damageIn(int[] histogram)
	{
		int total = 0;
		for (int d = 1; d < histogram.length; d++)
		{
			total += d * histogram[d];
		}
		return total;
	}

	/** The stretch of time the server is reporting on, when the owner has declared one. */
	@Getter
	public static class Epoch
	{
		private int id;
		private int startDay;

		@Nullable
		private String note;

		private boolean ready;

		/** @return the start day as {@code yyyy-mm-dd}, or null when there is no epoch. */
		@Nullable
		public String getStartLabel()
		{
			if (startDay < 10000101)
			{
				return null;
			}
			return String.format("%04d-%02d-%02d", startDay / 10000, (startDay / 100) % 100, startDay % 100);
		}
	}
}

package com.github.ilee2.hitstats.sync;

import com.github.ilee2.hitstats.HitStatsConfig;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Fetches community aggregates and keeps the answers for the session.
 *
 * <p>The panel asks for an answer and gets whatever is already cached, immediately; if that is
 * nothing or it has gone stale, a fetch is started on the executor and the panel is told to
 * repaint when it lands. Nothing here ever blocks the Swing thread or the client thread, so the
 * game cannot tell whether the server is up.
 *
 * <p>Answers are not refreshed more than once every {@link #REFRESH_MS}, which matches how often
 * the server rebuilds them. Asking sooner would return the same numbers.
 */
@Slf4j
@Singleton
public class CommunityClient
{
	private static final long REFRESH_MS = 5L * 60 * 1000;

	/** How long a lookup that failed is left alone for. */
	private static final long RETRY_MS = 5L * 60 * 1000;

	/** Stop the session cache growing without bound if someone sweeps every filter. */
	private static final int MAX_ENTRIES = 200;

	private final CommunitySync sync;
	private final HitStatsConfig config;
	private final SyncTransport transport;
	private final ScheduledExecutorService executor;
	private final Gson gson;

	private final Map<String, Entry> answers = new ConcurrentHashMap<>();
	private final Set<String> inFlight = ConcurrentHashMap.newKeySet();

	/**
	 * When a lookup that failed may be tried again. Without this a failing server would be asked
	 * again on every panel refresh, which is every two seconds.
	 */
	private final Map<String, Long> retryAfter = new ConcurrentHashMap<>();

	/** Bumped whenever an answer lands, so the panel knows it has something new to draw. */
	@Getter
	private volatile long revision;

	@Inject
	public CommunityClient(CommunitySync sync, HitStatsConfig config, SyncTransport transport,
		ScheduledExecutorService executor, Gson gson)
	{
		this.sync = sync;
		this.config = config;
		this.transport = transport;
		this.executor = executor;
		this.gson = gson;
	}

	/**
	 * @return the community answer for {@code query} if one is known, else null while a fetch runs.
	 * Starts that fetch when there is nothing cached or the answer has aged out.
	 */
	@Nullable
	public CommunityAggregate get(CommunityQuery query)
	{
		if (!config.showCommunity() || !query.isAskable() || sync.baseUrl().isEmpty())
		{
			return null;
		}

		final String key = query.cacheKey();
		final Entry cached = answers.get(key);
		if (cached == null || System.currentTimeMillis() - cached.fetchedAt > REFRESH_MS)
		{
			fetch(key, query);
		}
		if (cached == null)
		{
			return null;
		}
		cached.aggregate.setIncludeKillingBlows(config.includeKillingBlows());
		return cached.aggregate;
	}

	/** Whether a fetch for this lookup is running, so the panel can say "loading" rather than nothing. */
	public boolean isLoading(CommunityQuery query)
	{
		return inFlight.contains(query.cacheKey());
	}

	private void fetch(String key, CommunityQuery query)
	{
		final Long blockedUntil = retryAfter.get(key);
		if (blockedUntil != null && System.currentTimeMillis() < blockedUntil)
		{
			return;
		}
		if (!inFlight.add(key))
		{
			return;
		}

		final String url = query.toUrl(sync.baseUrl());
		executor.execute(() ->
		{
			try
			{
				final SyncTransport.Response response = transport.get(url);
				if (!response.isOk())
				{
					log.debug("Community query {} returned {}", key, response.getCode());
					retryAfter.put(key, System.currentTimeMillis() + RETRY_MS);
					return;
				}

				final CommunityAggregate parsed = gson.fromJson(response.getBody(), CommunityAggregate.class);
				if (parsed == null)
				{
					retryAfter.put(key, System.currentTimeMillis() + RETRY_MS);
					return;
				}
				retryAfter.remove(key);
				if (answers.size() >= MAX_ENTRIES)
				{
					answers.clear();
					retryAfter.clear();
				}
				answers.put(key, new Entry(parsed, System.currentTimeMillis()));
				revision++;
			}
			catch (IOException | RuntimeException e)
			{
				// A community comparison is a nicety. Losing one is not worth telling anyone about,
				// but it must not turn into a request every two seconds.
				retryAfter.put(key, System.currentTimeMillis() + RETRY_MS);
				log.debug("Community query failed", e);
			}
			finally
			{
				inFlight.remove(key);
			}
		});
	}

	public void clear()
	{
		answers.clear();
		inFlight.clear();
		retryAfter.clear();
		revision++;
	}

	private static class Entry
	{
		private final CommunityAggregate aggregate;
		private final long fetchedAt;

		Entry(CommunityAggregate aggregate, long fetchedAt)
		{
			this.aggregate = aggregate;
			this.fetchedAt = fetchedAt;
		}
	}
}

package com.github.ilee2.hitstats.sync;

import com.github.ilee2.hitstats.CombatContext;
import com.github.ilee2.hitstats.HistoryFilter;
import com.github.ilee2.hitstats.LevelMatch;
import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;

/**
 * One community lookup, as a URL. The parameters are the panel's own filter and nothing else, so
 * the community line and the player's line describe the same kind of setup; a server-side
 * dimension the panel cannot filter on would silently compare two different populations.
 *
 * <p>A weapon is required. "Every weapon at this monster" is not a distribution anyone can read,
 * and it is also the one shape broad enough to make the server work hard.
 */
public class CommunityQuery
{
	static final String PATH = "/v1/distribution";

	private final List<Integer> npcIds;
	private final Map<Integer, Integer> gear;

	@Nullable
	private final String attackLabel;

	@Nullable
	private final Boolean styleProtected;

	private final LevelMatch levels;

	/** Real level of the skill that drives this style's damage, or -1 when it is not known. */
	private final int anchorLevel;

	@Nullable
	private final int[] realLevels;

	@Nullable
	private final String me;

	public CommunityQuery(HistoryFilter filter, List<Integer> npcIds, LevelMatch levels,
		int anchorLevel, @Nullable int[] realLevels, @Nullable String me)
	{
		this.npcIds = new ArrayList<>(npcIds);
		Collections.sort(this.npcIds);
		this.gear = filter.getGear();
		this.attackLabel = filter.getAttackLabel();
		this.styleProtected = filter.getStyleProtected();
		this.levels = levels;
		this.anchorLevel = anchorLevel;
		this.realLevels = realLevels;
		this.me = me;
	}

	/**
	 * @return whether this is worth asking about: a monster, and either a weapon or a fully
	 * specified set of worn gear.
	 */
	public boolean isAskable()
	{
		return !npcIds.isEmpty()
			&& (gear.containsKey(CombatContext.WEAPON_SLOT) || gear.size() == CombatContext.GEAR_SLOTS);
	}

	public String toUrl(String baseUrl)
	{
		final StringBuilder sb = new StringBuilder(baseUrl).append(PATH).append("?npc=");
		for (int i = 0; i < npcIds.size(); i++)
		{
			if (i > 0)
			{
				sb.append(',');
			}
			sb.append(npcIds.get(i));
		}

		for (int slot = 0; slot < CombatContext.GEAR_SLOTS; slot++)
		{
			final Integer item = gear.get(slot);
			if (item != null)
			{
				sb.append("&s").append(slot).append('=').append(item);
			}
		}

		if (attackLabel != null && !attackLabel.isEmpty())
		{
			sb.append("&attack=").append(encode(attackLabel));
		}

		sb.append("&protected=");
		sb.append(styleProtected == null ? "any" : (styleProtected ? "1" : "0"));

		if (levels == LevelMatch.BRACKET && anchorLevel > 0)
		{
			sb.append("&levels=bracket&level=").append(anchorLevel);
		}
		else if (levels == LevelMatch.EXACT && realLevels != null
			&& realLevels.length == CombatContext.SKILL_NAMES.length)
		{
			sb.append("&levels=exact")
				.append("&rAtt=").append(realLevels[0])
				.append("&rStr=").append(realLevels[1])
				.append("&rRng=").append(realLevels[2])
				.append("&rMag=").append(realLevels[3]);
		}
		else
		{
			sb.append("&levels=any");
		}

		sb.append("&epoch=current");

		if (me != null && !me.isEmpty())
		{
			sb.append("&me=").append(encode(me));
		}
		return sb.toString();
	}

	/** Stable identity of this lookup, for the answer cache. */
	public String cacheKey()
	{
		return toUrl("");
	}

	private static String encode(String value)
	{
		try
		{
			return URLEncoder.encode(value, "UTF-8");
		}
		catch (UnsupportedEncodingException e)
		{
			// UTF-8 is required of every JVM.
			throw new IllegalStateException(e);
		}
	}
}

package com.github.ilee2.hitstats.sync;

import com.github.ilee2.hitstats.HitStatsConfig;
import com.github.ilee2.hitstats.HitStatsStore;
import com.google.gson.Gson;
import java.io.IOException;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.Locale;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Sends what has been recorded to the community server, when the player has opted in.
 *
 * <p>Nothing here is on the path of an attack. The upload runs on the plugin's executor, at most
 * one at a time, on the same occasions the history file is written: a timer, logging out, closing
 * the client, and once after logging in to catch up whatever a crash interrupted. A batch carries
 * cumulative counters, so every failure mode ends in the same place: send it again and the server
 * ignores what it already has.
 */
@Slf4j
@Singleton
public class CommunitySync
{
	/**
	 * Where the Worker lives. An empty value disables every request whatever the config says,
	 * which is what it held until the Worker was deployed on 2026-09-03. The hidden
	 * {@code serverUrl} setting overrides it for development against a local {@code wrangler dev}.
	 */
	static final String DEFAULT_BASE_URL = "https://osrs-hit-stats-worker.mayorhem.workers.dev";

	static final String SYNC_PATH = "/v1/sync";

	/**
	 * What this build calls itself to the server, which uses it to retire payload versions it no
	 * longer accepts. A plain constant on purpose: the Plugin Hub builds submissions in
	 * "standard" mode, which replaces build.gradle, so anything read from the jar manifest is
	 * present when built here and absent when built by the Hub. Keep it in step with the version
	 * in build.gradle.
	 */
	static final String CLIENT_VERSION = "1.1.0";

	/** Contexts per upload. Halved for the session if the server says a batch was too large. */
	private static final int MAX_BATCH = 2000;
	private static final int MIN_BATCH = 50;

	private static final long BASE_BACKOFF_MS = 5L * 60 * 1000;
	private static final long MAX_BACKOFF_MS = 60L * 60 * 1000;
	private static final long DAY_MS = 24L * 60 * 60 * 1000;

	private static final int HTTP_BAD_REQUEST = 400;
	private static final int HTTP_PAYLOAD_TOO_LARGE = 413;
	private static final int HTTP_UPGRADE_REQUIRED = 426;
	private static final int HTTP_TOO_MANY_REQUESTS = 429;
	private static final int HTTP_UNAVAILABLE = 503;

	public enum Reason
	{
		TIMER, LOGIN, LOGOUT, SHUTDOWN
	}

	private final HitStatsStore store;
	private final HitStatsConfig config;
	private final ConfigManager configManager;
	private final SyncTransport transport;
	private final ScheduledExecutorService executor;
	private final Gson gson;

	private final AtomicBoolean inFlight = new AtomicBoolean();

	private volatile int batchCap = MAX_BATCH;
	private volatile long nextAttemptAt;
	private volatile long backoffMs;
	private volatile long lastSuccessAt;
	private volatile long retiredUntil;

	/** Watermark of a batch the server rejected as malformed; not worth sending again unchanged. */
	private volatile long rejectedThrough = -1;

	@Nullable
	private volatile String failure;

	@Inject
	public CommunitySync(HitStatsStore store, HitStatsConfig config,
		ConfigManager configManager, SyncTransport transport, ScheduledExecutorService executor,
		Gson gson)
	{
		this.store = store;
		this.config = config;
		this.configManager = configManager;
		this.transport = transport;
		this.executor = executor;
		this.gson = gson;
	}

	/**
	 * Sends anything outstanding, unless uploads are off, the server is unreachable for now, or a
	 * request is already running.
	 *
	 * <p>The batch is captured on the calling thread and only the HTTP call is handed to the
	 * executor. That matters on logout: the store is unloaded moments later, and a capture that
	 * ran afterwards would find nothing.
	 *
	 * @return a future that completes when the request is done, so closing the client can wait
	 * briefly for it; already complete when there was nothing to send.
	 */
	public Future<?> upload(Reason reason)
	{
		if (!config.uploadEnabled() || baseUrl().isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}

		final long now = System.currentTimeMillis();
		if (now < retiredUntil || now < nextAttemptAt)
		{
			return CompletableFuture.completedFuture(null);
		}
		if (!inFlight.compareAndSet(false, true))
		{
			return CompletableFuture.completedFuture(null);
		}

		final UploadBatch batch;
		try
		{
			batch = store.pendingUpload(batchCap, installId(), clientVersion());
		}
		catch (RuntimeException e)
		{
			inFlight.set(false);
			log.debug("Unable to build a community upload", e);
			return CompletableFuture.completedFuture(null);
		}

		if (batch == null || batch.getThrough() == rejectedThrough)
		{
			// Nothing new, or the same records the server already called malformed.
			inFlight.set(false);
			return CompletableFuture.completedFuture(null);
		}

		return executor.submit(() ->
		{
			try
			{
				final byte[] body = OkHttpTransport.gzip(
					gson.toJson(batch).getBytes(StandardCharsets.UTF_8));
				log.debug("Community upload: {} contexts, {} bytes, {}", batch.size(), body.length, reason);
				onResponse(transport.post(baseUrl() + SYNC_PATH, body), batch);
			}
			catch (IOException | RuntimeException e)
			{
				// Never let an upload escape into the client. The watermark is untouched, so the
				// same records go again next time.
				failure = "upload failed";
				backOff(BASE_BACKOFF_MS);
				log.debug("Community upload failed", e);
			}
			finally
			{
				inFlight.set(false);
			}
		});
	}

	/** The whole failure policy, in one place. */
	private void onResponse(SyncTransport.Response response, UploadBatch batch)
	{
		final long now = System.currentTimeMillis();
		if (response.isOk())
		{
			store.markUploaded(batch);
			lastSuccessAt = now;
			failure = null;
			backoffMs = 0;
			nextAttemptAt = 0;
			rejectedThrough = -1;
			return;
		}

		switch (response.getCode())
		{
			case HTTP_BAD_REQUEST:
				// Our own payload is wrong. Retrying it unchanged cannot help.
				rejectedThrough = batch.getThrough();
				failure = "server rejected the data";
				log.debug("Community upload rejected: {}", response.getBody());
				break;
			case HTTP_PAYLOAD_TOO_LARGE:
				batchCap = Math.max(MIN_BATCH, batchCap / 2);
				failure = "batch too large, sending less";
				backOff(BASE_BACKOFF_MS);
				break;
			case HTTP_UPGRADE_REQUIRED:
				retiredUntil = now + DAY_MS;
				failure = "update the plugin";
				log.info("The community server no longer accepts this version of Hit Stats");
				break;
			case HTTP_TOO_MANY_REQUESTS:
			case HTTP_UNAVAILABLE:
				failure = "server busy";
				backOff(MAX_BACKOFF_MS);
				break;
			default:
				failure = "server error " + response.getCode();
				backOff(BASE_BACKOFF_MS);
				break;
		}
	}

	private void backOff(long floor)
	{
		backoffMs = Math.min(MAX_BACKOFF_MS, Math.max(floor, backoffMs * 2));
		nextAttemptAt = System.currentTimeMillis() + backoffMs;
	}

	/**
	 * @return the community base URL: the built-in one, or the hidden development override when
	 * it points somewhere this plugin is allowed to talk to.
	 *
	 * <p>The override exists so a sideloaded build can be tested against {@code wrangler dev} or
	 * the staging Worker. A hidden setting that could redirect uploads to <em>any</em> host would
	 * be an exfiltration route wearing a developer's coat, so anything but localhost and this
	 * plugin's own subdomain is ignored and logged.
	 */
	public String baseUrl()
	{
		final String override = config.serverUrl();
		if (override != null && !override.trim().isEmpty())
		{
			final String url = withoutTrailingSlash(override.trim());
			if (isAllowedHost(url))
			{
				return url;
			}
			log.warn("Ignoring the serverUrl override: {} is not localhost or {}", url, allowedSuffix());
		}
		return withoutTrailingSlash(DEFAULT_BASE_URL);
	}

	private static String withoutTrailingSlash(String url)
	{
		return url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
	}

	/** The built-in host with its first label removed: the subdomain this plugin's Workers live on. */
	private static String allowedSuffix()
	{
		final String host = hostOf(DEFAULT_BASE_URL);
		if (host == null)
		{
			return "";
		}
		final int dot = host.indexOf('.');
		return dot < 0 ? host : host.substring(dot + 1);
	}

	static boolean isAllowedHost(String url)
	{
		final String host = hostOf(url);
		if (host == null)
		{
			return false;
		}
		if ("localhost".equals(host) || "127.0.0.1".equals(host) || "[::1]".equals(host)
			|| "::1".equals(host))
		{
			return true;
		}

		final String suffix = allowedSuffix();
		return !suffix.isEmpty() && (host.equals(suffix) || host.endsWith("." + suffix));
	}

	@Nullable
	private static String hostOf(String url)
	{
		try
		{
			final String host = URI.create(url).getHost();
			return host == null ? null : host.toLowerCase(Locale.ROOT);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	/**
	 * A random id for this client installation, created once. It is sent so the server can tell
	 * two clients apart in its logs; it is not tied to an account and is not what the data is
	 * stored under, which is the per-file uploader id.
	 */
	private String installId()
	{
		final String existing = config.installId();
		if (existing != null && !existing.isEmpty())
		{
			return existing;
		}
		final String created = UUID.randomUUID().toString();
		configManager.setConfiguration(HitStatsConfig.GROUP, "installId", created);
		return created;
	}

	static String clientVersion()
	{
		return "hit-stats/" + CLIENT_VERSION;
	}

	/** One line for the bottom of the panel, or null when there is nothing worth saying. */
	@Nullable
	public String getStatus()
	{
		if (!config.uploadEnabled())
		{
			return null;
		}
		if (baseUrl().isEmpty())
		{
			return "Community: no server configured";
		}
		if (System.currentTimeMillis() < retiredUntil)
		{
			return "Community: update the plugin";
		}

		final String problem = failure;
		if (problem != null)
		{
			return "Community: " + problem + ", will retry";
		}
		if (lastSuccessAt == 0)
		{
			return "Community: nothing shared yet";
		}
		return "Community: shared " + ago(System.currentTimeMillis() - lastSuccessAt);
	}

	private static String ago(long millis)
	{
		final long minutes = millis / 60000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + " min ago";
		}
		return (minutes / 60) + " h ago";
	}
}

package com.github.ilee2.hitstats.sync;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.util.concurrent.TimeUnit;
import java.util.zip.GZIPOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.ResponseBody;

/**
 * {@link SyncTransport} over the client's own HTTP stack. RuneLite injects a configured
 * {@link OkHttpClient}; this takes a builder from it so the connection pool and proxy settings are
 * shared, and only the timeouts differ. A slow server must never hold an executor thread for long,
 * so both are short.
 */
@Singleton
public class OkHttpTransport implements SyncTransport
{
	private static final MediaType JSON = MediaType.parse("application/json");
	private static final int CONNECT_TIMEOUT_SECONDS = 5;
	private static final int READ_TIMEOUT_SECONDS = 10;

	private final OkHttpClient client;
	private final String userAgent;

	@Inject
	public OkHttpTransport(OkHttpClient shared)
	{
		this.client = shared.newBuilder()
			.connectTimeout(CONNECT_TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.readTimeout(READ_TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.build();
		this.userAgent = CommunitySync.clientVersion();
	}

	@Override
	public SyncTransport.Response post(String url, byte[] body) throws IOException
	{
		return send(new Request.Builder()
			.url(url)
			.header("User-Agent", userAgent)
			.header("Content-Encoding", "gzip")
			.post(RequestBody.create(JSON, body))
			.build());
	}

	@Override
	public SyncTransport.Response get(String url) throws IOException
	{
		return send(new Request.Builder()
			.url(url)
			.header("User-Agent", userAgent)
			.get()
			.build());
	}

	private SyncTransport.Response send(Request request) throws IOException
	{
		try (okhttp3.Response response = client.newCall(request).execute())
		{
			final ResponseBody body = response.body();
			return new SyncTransport.Response(response.code(), body == null ? "" : body.string());
		}
	}

	/** Gzips {@code json} for {@link #post}. OkHttp does not compress request bodies itself. */
	public static byte[] gzip(byte[] json) throws IOException
	{
		final ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(32, json.length / 4));
		try (OutputStream gz = new GZIPOutputStream(out))
		{
			gz.write(json);
		}
		return out.toByteArray();
	}
}

package com.github.ilee2.hitstats.sync;

import java.io.IOException;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The two HTTP calls this plugin makes, behind an interface so the upload and query logic can be
 * tested without a network or an extra test dependency. The real implementation is
 * {@link OkHttpTransport}.
 */
public interface SyncTransport
{
	/** @param body already gzipped JSON; the implementation sets {@code Content-Encoding}. */
	Response post(String url, byte[] body) throws IOException;

	Response get(String url) throws IOException;

	@Getter
	@RequiredArgsConstructor
	class Response
	{
		private final int code;
		private final String body;

		public boolean isOk()
		{
			return code >= 200 && code < 300;
		}
	}
}

package com.github.ilee2.hitstats.sync;

import com.github.ilee2.hitstats.CombatContext;
import com.github.ilee2.hitstats.ContextStats;
import com.github.ilee2.hitstats.NpcName;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Getter;

/**
 * One upload, exactly as it goes over the wire. Every record carries its cumulative counters
 * rather than what changed since last time, so re-sending a batch cannot double count anything:
 * the server replaces a record instead of adding to it. That is what makes a retry after a
 * timeout, a crash between the response and the next save, and an out-of-order arrival all
 * harmless.
 *
 * <p>Field names are the wire format. Renaming one is a payload change and needs {@link #v}
 * bumped and the server taught the new shape.
 */
@Getter
public class UploadBatch
{
	/** Payload version. The server accepts exactly one; see the plan's section 8.5. */
	private final int v = 1;

	private final String uploader;
	private final String install;
	private final String client;

	/**
	 * The history file format that produced these keys. The key is a hash of the context's
	 * fields, so a future format that changes what goes into it produces different keys for the
	 * same setup; the server needs to be able to tell those generations apart.
	 */
	private final int keyVersion;

	private final long sentAt;
	private final List<Context> contexts;
	private final Map<Integer, NpcName> npcNames;
	private final Map<Integer, String> itemNames;

	/** Not serialised: who the batch was built for, so a late response cannot credit another login. */
	private final transient String player;

	/** Not serialised: the watermark to store when the server accepts this batch. */
	private final transient long through;

	public UploadBatch(String uploader, String install, String client, int keyVersion,
		List<ContextStats> records, Map<Integer, NpcName> npcNames, Map<Integer, String> itemNames,
		String player)
	{
		this.uploader = uploader;
		this.install = install;
		this.client = client;
		this.keyVersion = keyVersion;
		this.sentAt = System.currentTimeMillis();
		this.npcNames = npcNames;
		this.itemNames = itemNames;
		this.player = player;

		this.contexts = new ArrayList<>(records.size());
		long latest = 0;
		for (ContextStats stats : records)
		{
			contexts.add(new Context(stats));
			latest = Math.max(latest, stats.getLastSeen());
		}
		this.through = latest;
	}

	public int size()
	{
		return contexts.size();
	}

	/** One recorded setup and everything counted under it. */
	@Getter
	public static class Context
	{
		private final String key;
		private final CombatContext ctx;
		private final int[] counts;

		@Nullable
		private final int[] killCounts;

		private final int attacks;
		private final int hitsplats;
		private final int splashes;
		private final int maxHits;
		private final int killingBlows;
		private final int killingBlowMaxHits;
		private final int wastedTicks;
		private final int activeTicks;
		private final long firstSeen;
		private final long lastSeen;

		Context(ContextStats stats)
		{
			this.key = stats.getContext().getKey();
			this.ctx = stats.getContext();
			this.counts = stats.getCounts();
			this.killCounts = stats.getKillCounts().length == 0 ? null : stats.getKillCounts();
			this.attacks = stats.getAttacks();
			this.hitsplats = stats.getHitsplats();
			this.splashes = stats.getSplashes();
			this.maxHits = stats.getMaxHits();
			this.killingBlows = stats.getKillingBlows();
			this.killingBlowMaxHits = stats.getKillingBlowMaxHits();
			this.wastedTicks = stats.getWastedTicks();
			this.activeTicks = stats.getActiveTicks();
			this.firstSeen = stats.getFirstSeen();
			this.lastSeen = stats.getLastSeen();
		}
	}
}

package com.github.ilee2.hitstats.ui;

import com.github.ilee2.hitstats.CombatContext;
import com.github.ilee2.hitstats.FilterOptions;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Filter by worn equipment by clicking the slot you care about, laid out the way the game lays
 * out the equipment tab. Eleven dropdowns would have swamped the panel; eleven boxes in the shape
 * players already know do not.
 *
 * <p>A slot with a filter on it shows the chosen item and an orange border. Clicking a slot lists
 * only what was actually worn there in the hits that match the rest of the filter, including
 * having worn nothing there: "no shield" and "any shield" are different questions, and both are
 * askable.
 */
class EquipmentFilterPanel extends JPanel
{
	interface SlotListener
	{
		/** @param itemId the item required in this slot, or null to stop filtering on it. */
		void slotChanged(int slot, @Nullable Integer itemId);
	}

	private static final int CELL = 32;
	private static final int GAP = 2;
	private static final int MAX_SUGGESTIONS = 20;

	/**
	 * Text drawn in a slot pinned to "nothing was worn here". Plain ASCII: the RuneScape fonts
	 * have no glyph for the symbols that would say this more compactly.
	 */
	private static final String NOTHING_MARK = "none";

	private static final Color EMPTY_SLOT = new Color(40, 40, 40);
	private static final Color SLOT_BORDER = new Color(70, 70, 70);
	private static final Color UNUSED_SLOT = new Color(30, 30, 30);

	private final ItemManager itemManager;
	private final SlotListener listener;
	private final Map<Integer, JLabel> cells = new HashMap<>();

	private Map<Integer, List<FilterOptions.Option>> options = Collections.emptyMap();
	private Map<Integer, Integer> selection = Collections.emptyMap();

	EquipmentFilterPanel(ItemManager itemManager, SlotListener listener)
	{
		this.itemManager = itemManager;
		this.listener = listener;

		setLayout(new GridLayout(EquipmentLayout.SLOTS.length, EquipmentLayout.COLUMNS, GAP, GAP));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final int width = EquipmentLayout.COLUMNS * CELL + (EquipmentLayout.COLUMNS - 1) * GAP;
		final int height = EquipmentLayout.SLOTS.length * CELL + (EquipmentLayout.SLOTS.length - 1) * GAP;
		final Dimension size = new Dimension(width, height);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);

		for (EquipmentInventorySlot[] row : EquipmentLayout.SLOTS)
		{
			for (EquipmentInventorySlot slot : row)
			{
				add(cell(slot));
			}
		}
	}

	void setOptions(Map<Integer, List<FilterOptions.Option>> options)
	{
		this.options = options;
		render();
	}

	void setSelection(Map<Integer, Integer> selection)
	{
		this.selection = selection;
		render();
	}

	private JLabel cell(@Nullable EquipmentInventorySlot slot)
	{
		final JLabel label = new JLabel();
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setVerticalAlignment(SwingConstants.CENTER);
		label.setPreferredSize(new Dimension(CELL, CELL));
		label.setFont(FontManager.getRunescapeSmallFont());

		if (slot == null)
		{
			label.setOpaque(false);
			return label;
		}

		label.setOpaque(true);
		final int index = slot.getSlotIdx();
		cells.put(index, label);

		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				showChoices(slot, label);
			}
		});

		return label;
	}

	private void render()
	{
		for (EquipmentInventorySlot[] row : EquipmentLayout.SLOTS)
		{
			for (EquipmentInventorySlot slot : row)
			{
				if (slot == null)
				{
					continue;
				}

				final int index = slot.getSlotIdx();
				final JLabel label = cells.get(index);
				if (label == null)
				{
					continue;
				}

				final boolean usable = options.containsKey(index);
				final Integer chosen = selection.get(index);

				label.setIcon(null);
				label.setText("");
				label.setBackground(usable ? EMPTY_SLOT : UNUSED_SLOT);
				label.setBorder(BorderFactory.createLineBorder(
					chosen != null ? ColorScheme.BRAND_ORANGE : SLOT_BORDER));
				label.setCursor(Cursor.getPredefinedCursor(usable ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));

				if (chosen == null)
				{
					label.setToolTipText(usable
						? EquipmentLayout.name(slot) + ": any"
						: EquipmentLayout.name(slot) + ": nothing recorded");
					continue;
				}

				if (isNothing(chosen))
				{
					// An unfiltered slot is also drawn empty, so the pinned-to-nothing case needs
					// a mark of its own or the two read the same at a glance.
					label.setText(NOTHING_MARK);
					label.setForeground(ColorScheme.BRAND_ORANGE);
				}
				else
				{
					final AsyncBufferedImage image = itemManager.getImage(chosen);
					image.addTo(label);
				}
				label.setToolTipText(EquipmentLayout.name(slot) + ": " + labelFor(index, chosen));
			}
		}

		revalidate();
		repaint();
	}

	private String labelFor(int slot, int itemId)
	{
		for (FilterOptions.Option option : options.getOrDefault(slot, Collections.emptyList()))
		{
			if (option.getId() != null && option.getId() == itemId)
			{
				return option.getLabel();
			}
		}
		if (isNothing(itemId))
		{
			return slot == CombatContext.WEAPON_SLOT ? "Unarmed" : "Nothing";
		}
		return "item " + itemId;
	}

	/** The store writes {@link CombatContext#NO_ITEM} for an empty slot; be lenient about 0. */
	private static boolean isNothing(@Nullable Integer itemId)
	{
		return itemId != null && itemId <= 0;
	}

	private JMenuItem choice(int slot, FilterOptions.Option option)
	{
		final Integer itemId = option.getId();
		final JMenuItem item = new JMenuItem(option.getLabel() + "  (" + option.getAttacks() + ")");
		item.setFont(FontManager.getRunescapeSmallFont());
		if (!isNothing(itemId))
		{
			final AsyncBufferedImage image = itemManager.getImage(itemId, 1, false);
			item.setIcon(new ImageIcon(image));
			image.onLoaded(item::repaint);
		}
		item.addActionListener(e -> listener.slotChanged(slot, itemId));
		return item;
	}

	private void showChoices(EquipmentInventorySlot slot, JLabel anchor)
	{
		final int index = slot.getSlotIdx();
		final List<FilterOptions.Option> choices = options.get(index);
		if (choices == null || choices.isEmpty())
		{
			return;
		}

		final JPopupMenu popup = new JPopupMenu();
		popup.setFocusable(false);

		final JMenuItem any = new JMenuItem("Any " + EquipmentLayout.name(slot).toLowerCase());
		any.setFont(FontManager.getRunescapeSmallFont());
		any.setToolTipText("Do not filter on this slot");
		any.addActionListener(e -> listener.slotChanged(index, null));
		popup.add(any);

		// "Worn nothing here" is a choice like any other, but it is one attack among thousands in
		// most histories, so it is lifted out of the sorted list rather than left to be cut off by
		// the suggestion cap. It also sits next to "Any", which is the option it is confused with.
		final List<FilterOptions.Option> items = new ArrayList<>(choices.size());
		FilterOptions.Option nothing = null;
		for (FilterOptions.Option option : choices)
		{
			if (isNothing(option.getId()))
			{
				nothing = option;
			}
			else
			{
				items.add(option);
			}
		}

		if (nothing != null)
		{
			popup.add(choice(index, nothing));
		}

		popup.addSeparator();

		int shown = 0;
		for (FilterOptions.Option option : items)
		{
			if (shown++ >= MAX_SUGGESTIONS)
			{
				final JMenuItem more = new JMenuItem((items.size() - MAX_SUGGESTIONS) + " more not shown");
				more.setFont(FontManager.getRunescapeSmallFont());
				more.setEnabled(false);
				popup.add(more);
				break;
			}
			popup.add(choice(index, option));
		}

		popup.show(anchor, 0, anchor.getHeight());
	}
}

package com.github.ilee2.hitstats.ui;

import javax.annotation.Nullable;
import net.runelite.api.EquipmentInventorySlot;

/** The game's worn-equipment arrangement, shared by the read-only view and the filter. */
final class EquipmentLayout
{
	static final int COLUMNS = 3;

	/**
	 * Arms, hair and jaw are real slots but hold nothing a player equips, so they are left out
	 * rather than drawn as permanently empty boxes.
	 */
	static final EquipmentInventorySlot[][] SLOTS = {
		{null, EquipmentInventorySlot.HEAD, null},
		{EquipmentInventorySlot.CAPE, EquipmentInventorySlot.AMULET, EquipmentInventorySlot.AMMO},
		{EquipmentInventorySlot.WEAPON, EquipmentInventorySlot.BODY, EquipmentInventorySlot.SHIELD},
		{null, EquipmentInventorySlot.LEGS, null},
		{EquipmentInventorySlot.GLOVES, EquipmentInventorySlot.BOOTS, EquipmentInventorySlot.RING},
	};

	private EquipmentLayout()
	{
	}

	static String name(@Nullable EquipmentInventorySlot slot)
	{
		if (slot == null)
		{
			return "";
		}

		switch (slot)
		{
			case HEAD:
				return "Head";
			case CAPE:
				return "Cape";
			case AMULET:
				return "Amulet";
			case WEAPON:
				return "Weapon";
			case BODY:
				return "Body";
			case SHIELD:
				return "Shield";
			case LEGS:
				return "Legs";
			case GLOVES:
				return "Gloves";
			case BOOTS:
				return "Boots";
			case RING:
				return "Ring";
			case AMMO:
				return "Ammo";
			default:
				return slot.name();
		}
	}
}

package com.github.ilee2.hitstats.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import javax.annotation.Nullable;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;

/**
 * The worn equipment of one recorded context, drawn as item icons in the same arrangement the
 * game's worn-equipment tab uses.
 */
class EquipmentPanel extends JPanel
{
	private static final int CELL = 32;
	private static final int GAP = 2;
	private static final Color EMPTY_SLOT = new Color(40, 40, 40);

	EquipmentPanel(ItemManager itemManager, int[] gear)
	{
		setLayout(new GridLayout(EquipmentLayout.SLOTS.length, EquipmentLayout.COLUMNS, GAP, GAP));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);

		final int width = EquipmentLayout.COLUMNS * CELL + (EquipmentLayout.COLUMNS - 1) * GAP;
		final int height = EquipmentLayout.SLOTS.length * CELL + (EquipmentLayout.SLOTS.length - 1) * GAP;
		final Dimension size = new Dimension(width, height);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);

		for (EquipmentInventorySlot[] row : EquipmentLayout.SLOTS)
		{
			for (EquipmentInventorySlot slot : row)
			{
				add(cell(itemManager, gear, slot));
			}
		}
	}

	private JLabel cell(ItemManager itemManager, int[] gear, @Nullable EquipmentInventorySlot slot)
	{
		final JLabel label = new JLabel();
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setVerticalAlignment(SwingConstants.CENTER);
		label.setPreferredSize(new Dimension(CELL, CELL));

		if (slot == null)
		{
			// A gap in the layout, not an empty slot: draw nothing at all.
			label.setOpaque(false);
			return label;
		}

		label.setOpaque(true);
		label.setBackground(EMPTY_SLOT);

		final int index = slot.getSlotIdx();
		final int itemId = index >= 0 && index < gear.length ? gear[index] : -1;
		if (itemId > 0)
		{
			// Loads from the item cache and repaints the label when it arrives.
			itemManager.getImage(itemId).addTo(label);
		}

		return label;
	}
}

package com.github.ilee2.hitstats.ui;

import com.github.ilee2.hitstats.FilterOptions;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.annotation.Nullable;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.MenuElement;
import javax.swing.MenuSelectionManager;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * A search box that doubles as a dropdown: type to narrow the list, or open it with the arrow to
 * see everything recorded. Picking an entry sets the filter; the clear button drops back to "all".
 *
 * <p>Same shape as the search in the GE Helper plugin -- an {@link IconTextField} with a
 * {@link JPopupMenu} of suggestions under it, driven by the keyboard as well as the mouse.
 */
class FilterSelect extends JPanel
{
	/** Longer lists are truncated rather than filling the screen; typing narrows them. */
	private static final int MAX_SUGGESTIONS = 15;

	private static final int HEIGHT = 24;

	private final IconTextField field = new IconTextField();
	private final JPopupMenu popup = new JPopupMenu();
	private final String allLabel;
	private final Runnable onChange;

	/** Only set for lists whose ids are item ids, so the suggestions can carry item icons. */
	@Nullable
	private final ItemManager itemManager;

	private List<FilterOptions.Option> options = Collections.emptyList();

	/** null means no filter on this dimension. */
	@Nullable
	private FilterOptions.Option selected;

	private int highlighted = -1;

	/** Set while the field's text is being written programmatically rather than typed. */
	private boolean suppressSuggestions;

	/** What the open popup was built from: the typed text, or "" when the arrow listed everything. */
	private String lastQuery = "";

	FilterSelect(String allLabel, @Nullable ItemManager itemManager, Runnable onChange)
	{
		this.allLabel = allLabel;
		this.itemManager = itemManager;
		this.onChange = onChange;

		setLayout(new BorderLayout(2, 0));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setPreferredSize(new Dimension(100, HEIGHT));

		field.setIcon(IconTextField.Icon.SEARCH);
		field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		field.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		field.setPreferredSize(new Dimension(100, HEIGHT));
		field.setMinimumSize(new Dimension(0, HEIGHT));
		field.setToolTipText("Type to search, or use the arrow to list everything");
		add(field, BorderLayout.CENTER);

		add(arrow(), BorderLayout.EAST);

		popup.setFocusable(false);

		field.addClearListener(() ->
		{
			setFieldText("");
			popup.setVisible(false);
			if (selected != null)
			{
				selected = null;
				onChange.run();
			}
		});

		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				showSuggestions();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				showSuggestions();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				showSuggestions();
			}
		});

		field.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				onKey(e);
			}
		});
	}

	// ------------------------------------------------------------------ state

	/**
	 * Replaces the choices offered. The current selection is deliberately left alone even when it
	 * is no longer among them: it can drop out because of the other filters, and silently
	 * resetting it would change the numbers on screen without the user asking.
	 */
	void setOptions(List<FilterOptions.Option> options)
	{
		this.options = options;

		// The panel refreshes every couple of seconds while fighting. A list left open across
		// that would keep showing the counts from before the refresh.
		if (popup.isVisible())
		{
			buildPopup(lastQuery);
		}
	}

	@Nullable
	FilterOptions.Option getSelected()
	{
		return selected;
	}

	/** Shows a selection made elsewhere, without calling back. */
	void setSelected(@Nullable FilterOptions.Option option)
	{
		selected = option;
		setFieldText(option == null ? "" : option.getLabel());
		popup.setVisible(false);
	}

	/** Drops back to "all" without notifying; the caller refreshes once for all of its boxes. */
	void clear()
	{
		selected = null;
		setFieldText("");
		popup.setVisible(false);
	}

	private void select(@Nullable FilterOptions.Option option)
	{
		selected = option;
		setFieldText(option == null ? "" : option.getLabel());
		popup.setVisible(false);
		highlighted = -1;
		onChange.run();
	}

	// -------------------------------------------------------------------- ui

	private JLabel arrow()
	{
		// Down-pointing triangle, as an escape so the source stays pure ASCII.
		final JLabel label = new JLabel("\u25be");
		label.setFont(FontManager.getDefaultFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.setToolTipText("Show everything recorded");
		label.setBorder(new EmptyBorder(0, 2, 0, 4));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (popup.isVisible())
				{
					popup.setVisible(false);
					return;
				}
				// The arrow lists everything, whatever is typed in the box.
				buildPopup("");
			}
		});
		return label;
	}

	private void onKey(KeyEvent e)
	{
		if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
		{
			popup.setVisible(false);
			return;
		}

		// Arrow keys drive the suggestions; without consuming them the sidebar's scroll pane
		// takes them as well and the whole panel jumps.
		if (e.getKeyCode() == KeyEvent.VK_DOWN && !popup.isVisible())
		{
			buildPopup(field.getText());
			e.consume();
			return;
		}

		if (!popup.isVisible())
		{
			return;
		}

		final int count = popup.getComponentCount();
		if (count == 0)
		{
			return;
		}

		if (e.getKeyCode() == KeyEvent.VK_DOWN)
		{
			highlighted = highlighted + 1 >= count ? 0 : highlighted + 1;
			highlight();
			e.consume();
		}
		else if (e.getKeyCode() == KeyEvent.VK_UP)
		{
			highlighted = highlighted - 1 < 0 ? count - 1 : highlighted - 1;
			highlight();
			e.consume();
		}
		else if (e.getKeyCode() == KeyEvent.VK_ENTER)
		{
			final int index = highlighted >= 0 ? highlighted : 0;
			final java.awt.Component item = popup.getComponent(index);
			if (item instanceof JMenuItem && item.isEnabled())
			{
				((JMenuItem) item).doClick();
				e.consume();
			}
		}
	}

	private void highlight()
	{
		if (highlighted < 0 || highlighted >= popup.getComponentCount())
		{
			return;
		}
		final java.awt.Component item = popup.getComponent(highlighted);
		if (!(item instanceof MenuElement))
		{
			return;
		}
		MenuSelectionManager.defaultManager().setSelectedPath(new MenuElement[]{popup, (MenuElement) item});
	}

	private void setFieldText(String text)
	{
		suppressSuggestions = true;
		try
		{
			field.setText(text);
		}
		finally
		{
			suppressSuggestions = false;
		}
	}

	private void showSuggestions()
	{
		if (suppressSuggestions)
		{
			return;
		}
		buildPopup(field.getText());
	}

	private void buildPopup(@Nullable String query)
	{
		final String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		lastQuery = needle;

		popup.removeAll();
		highlighted = -1;

		final JMenuItem all = new JMenuItem(allLabel);
		all.setFont(FontManager.getRunescapeSmallFont());
		all.addActionListener(e -> select(null));
		popup.add(all);

		int shown = 0;
		int matched = 0;
		for (FilterOptions.Option option : options)
		{
			if (!needle.isEmpty() && !option.getLabel().toLowerCase(Locale.ROOT).contains(needle))
			{
				continue;
			}

			matched++;
			if (shown >= MAX_SUGGESTIONS)
			{
				continue;
			}
			shown++;

			final JMenuItem item = new JMenuItem(option.getLabel() + "  (" + option.getAttacks() + ")");
			item.setFont(FontManager.getRunescapeSmallFont());
			icon(option, item);
			item.addActionListener(e -> select(option));
			popup.add(item);
		}

		if (matched > shown)
		{
			final JMenuItem more = new JMenuItem((matched - shown) + " more, keep typing");
			more.setFont(FontManager.getRunescapeSmallFont());
			more.setEnabled(false);
			popup.add(more);
		}

		if (!field.isShowing())
		{
			return;
		}

		popup.pack();
		if (popup.isVisible())
		{
			popup.revalidate();
			popup.repaint();
		}
		else
		{
			popup.show(field, 0, field.getHeight());
		}
	}

	private void icon(FilterOptions.Option option, JMenuItem item)
	{
		final Integer id = option.getId();
		if (itemManager == null || id == null || id <= 0)
		{
			return;
		}

		final AsyncBufferedImage image = itemManager.getImage(id, 1, false);
		item.setIcon(new ImageIcon(image));
		image.onLoaded(item::repaint);
	}
}

package com.github.ilee2.hitstats.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.event.MouseEvent;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The damage distribution, one horizontal bar per hitsplat amount, with the amount labelled on the
 * left and its count at the end of the bar.
 *
 * <p>Horizontal because vertical bars in a sidebar leave a few pixels per column, which is not
 * enough for a readable label once a weapon can hit past twenty. Every damage bar is drawn to
 * scale against the longest damage bar, so their lengths can be compared directly.
 *
 * <p>Misses and splashes are the exception. They routinely outnumber any single damage value
 * several times over, and scaling to them would squash every real bar to nothing, so those two
 * run off the end of the chart with a torn edge and their true count beside them. They sit above
 * a divider, apart from the damage they are not part of.
 *
 * <p>When a community distribution is supplied it is drawn as a line across the bars, at the point
 * on each row where everyone else's share of that damage falls, and both series switch to
 * <em>share of attempts</em> rather than raw counts. Everyone else together has thousands of times
 * more hits than one player, so raw counts would draw one visible series and one flat line; shares
 * are the only way the two shapes can be compared. A line rather than a second bar because the
 * question is where your bar sits against theirs, and a bar that crosses the line answers it
 * without the eye having to pair up two rows.
 */
public class HistogramPanel extends JPanel
{
	private static final int ROW_HEIGHT = 13;
	private static final int BAR_HEIGHT = 9;

	private static final int GUTTER = 22;
	private static final int LEFT_PAD = 2;
	private static final int RIGHT_PAD = 4;
	private static final int TOP_PAD = 3;
	private static final int BOTTOM_PAD = 3;
	private static final int COUNT_GAP = 4;
	private static final int DIVIDER_HEIGHT = 5;
	private static final int MIN_BAR = 2;

	private static final Color HIT_COLOR = ColorScheme.BRAND_ORANGE;
	private static final Color MAX_COLOR = new Color(255, 200, 80);
	private static final Color MISS_COLOR = new Color(120, 120, 120);
	private static final Color SPLASH_COLOR = new Color(140, 122, 230);
	private static final Color AXIS_COLOR = new Color(150, 150, 150);
	private static final Color DIVIDER_COLOR = new Color(70, 70, 70);
	private static final Color HOVER_COLOR = new Color(255, 255, 255, 40);

	/** Drawn under the community line so it stays legible where it crosses a bar. */
	private static final Color LINE_HALO_COLOR = new Color(20, 20, 20, 190);

	private static final Stroke LINE_STROKE =
		new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final Stroke LINE_HALO_STROKE =
		new BasicStroke(3.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

	/** Killing blows, both in their bar segments here and wherever the panel refers to them. */
	public static final Color KILL_COLOR = new Color(196, 96, 70);

	/** Everyone else's distribution. Cool against the warm bars so the two never read as one. */
	public static final Color COMMUNITY_COLOR = new Color(120, 180, 225);

	/** One bar: a hitsplat amount, or the miss or splash tally. */
	private static class Row
	{
		private final String label;
		private final String tooltip;
		private final int count;
		private final Color color;

		/** Miss and splash rows are not part of the damage scale and may run off the end. */
		private final boolean offScale;

		/** How many of {@link #count} ended a fight; drawn as a segment at the end of the bar. */
		private final int killCount;

		/** The same amount across everyone else, or -1 when there is no community series. */
		private int otherCount = -1;

		Row(String label, String tooltip, int count, Color color, boolean offScale, int killCount)
		{
			this.label = label;
			this.tooltip = tooltip;
			this.count = count;
			this.color = color;
			this.offScale = offScale;
			this.killCount = killCount;
		}
	}

	private List<Row> rows = new ArrayList<>();
	private int peak;
	private int total;

	/** Attempts across everyone else, so their bars can be drawn as shares. 0 when absent. */
	private int otherTotal;

	private boolean paired;

	/** Index of the first damage row, which is where the divider goes. */
	private int firstDamageRow;

	private int hoverRow = -1;

	public HistogramPanel()
	{
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setToolTipText("");
		setPreferredSize(new Dimension(0, height()));
		setMinimumSize(new Dimension(50, height()));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height()));

		addMouseMotionListener(new java.awt.event.MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				final int row = rowAt(e.getY());
				if (row != hoverRow)
				{
					hoverRow = row;
					repaint();
				}
			}
		});
		addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseExited(MouseEvent e)
			{
				hoverRow = -1;
				repaint();
			}
		});
	}

	/**
	 * @param killCounts killing blows by damage that are folded into {@code counts}, so they can
	 * be picked out within their bars. Empty when they are not charted.
	 */
	public void setData(int[] counts, int[] killCounts, int splashes, int highestHit)
	{
		setData(counts, killCounts, splashes, highestHit, null, 0);
	}

	/**
	 * @param otherCounts everyone else's hitsplats by damage, or null to draw this player alone.
	 * @param otherSplashes their splashes, which count towards their attempts the same way.
	 */
	public void setData(int[] counts, int[] killCounts, int splashes, int highestHit,
		@Nullable int[] otherCounts, int otherSplashes)
	{
		final List<Row> built = new ArrayList<>();
		int attempts = splashes;

		if (splashes > 0 || (otherCounts != null && otherSplashes > 0))
		{
			built.add(new Row("S", "Splash", splashes, SPLASH_COLOR, true, 0));
		}

		if (counts.length > 0)
		{
			built.add(new Row("0", "Miss", counts[0], MISS_COLOR, true, 0));
			attempts += counts[0];
		}

		firstDamageRow = built.size();

		// Long enough for both series: a damage value only they have reached still gets a row.
		final int width = Math.max(counts.length, otherCounts == null ? 0 : otherCounts.length);

		int highest = 0;
		for (int d = 1; d < width; d++)
		{
			final int mine = d < counts.length ? counts[d] : 0;
			final int kills = d < killCounts.length ? Math.min(killCounts[d], mine) : 0;
			built.add(new Row(Integer.toString(d), "Hit " + d, mine,
				d == highestHit ? MAX_COLOR : HIT_COLOR, false, kills));
			attempts += mine;
			highest = Math.max(highest, mine);
		}

		paired = otherCounts != null;
		otherTotal = 0;
		if (paired)
		{
			otherTotal = otherSplashes;
			for (int d = 0; d < otherCounts.length; d++)
			{
				otherTotal += otherCounts[d];
			}
			for (int i = 0; i < built.size(); i++)
			{
				final Row row = built.get(i);
				if (i < firstDamageRow)
				{
					row.otherCount = "S".equals(row.label)
						? otherSplashes
						: (otherCounts.length > 0 ? otherCounts[0] : 0);
				}
				else
				{
					final int d = i - firstDamageRow + 1;
					row.otherCount = d < otherCounts.length ? otherCounts[d] : 0;
				}
			}
		}

		rows = built;
		peak = highest;
		total = attempts;
		hoverRow = -1;

		final Dimension size = new Dimension(0, height());
		setPreferredSize(size);
		setMinimumSize(new Dimension(50, size.height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, size.height));

		revalidate();
		repaint();
	}

	private int height()
	{
		if (rows == null || rows.isEmpty())
		{
			return 28;
		}
		return TOP_PAD + rows.size() * ROW_HEIGHT + BOTTOM_PAD
			+ (firstDamageRow > 0 ? DIVIDER_HEIGHT : 0);
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		final int index = rowAt(event.getY());
		if (index < 0)
		{
			return null;
		}

		final Row row = rows.get(index);
		final String kills = row.killCount == 0
			? ""
			: ", " + row.killCount + (row.killCount == 1 ? " killing blow" : " killing blows");

		if (!paired)
		{
			return String.format("%s: %d (%s)", row.tooltip, row.count, percent(row.count, total)) + kills;
		}

		return "<html>" + row.tooltip
			+ "<br>You: " + row.count + " (" + percent(row.count, total) + ")" + kills
			+ "<br>Everyone: " + Math.max(0, row.otherCount)
			+ " (" + percent(Math.max(0, row.otherCount), otherTotal) + ")</html>";
	}

	private static String percent(int part, int whole)
	{
		return whole <= 0 ? "0.0%" : String.format("%.1f%%", 100.0 * part / whole);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);

		final Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g2.setFont(FontManager.getRunescapeSmallFont());
			paint(g2);
		}
		finally
		{
			g2.dispose();
		}
	}

	private void paint(Graphics2D g)
	{
		final FontMetrics fm = g.getFontMetrics();

		if (rows.isEmpty())
		{
			g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			final String msg = "No hits recorded yet";
			g.drawString(msg, (getWidth() - fm.stringWidth(msg)) / 2, getHeight() / 2 + fm.getAscent() / 2);
			return;
		}

		final int barLeft = LEFT_PAD + GUTTER;
		final int countWidth = fm.stringWidth(Integer.toString(widestCount())) + COUNT_GAP;
		final int barMax = Math.max(MIN_BAR, getWidth() - barLeft - RIGHT_PAD - countWidth);

		// Alone, bars are counts against the tallest count. Beside the community they are shares
		// against the tallest share of either series, which is the only comparable scale.
		final double scale = paired ? peakShare() : Math.max(1, peak);

		// Where each bar's count label goes. Held back until after the community line, so the line
		// never runs through a number.
		final int[] countX = new int[rows.size()];

		for (int i = 0; i < rows.size(); i++)
		{
			final Row row = rows.get(i);
			final int y = rowTop(i);

			if (i == hoverRow)
			{
				g.setColor(HOVER_COLOR);
				g.fillRect(0, y, getWidth(), ROW_HEIGHT);
			}

			// Amount, right-aligned into its own column so the bars all start together.
			g.setColor(AXIS_COLOR);
			final int labelWidth = fm.stringWidth(row.label);
			g.drawString(row.label, barLeft - COUNT_GAP - labelWidth, y + fm.getAscent());

			final int barY = barTop(i);

			if (row.count > 0)
			{
				final double value = paired ? share(row.count, total) : row.count;
				final boolean runsOff = row.offScale && value > scale;
				final int length = runsOff
					? barMax
					: Math.max(MIN_BAR, (int) Math.round(barMax * value / scale));

				g.setColor(row.color);
				g.fillRect(barLeft, barY, length, BAR_HEIGHT);

				if (row.killCount > 0 && !runsOff)
				{
					// The killing blows sit at the end of their bar in their own colour, so a bar
					// that owes part of its length to capped hits says so.
					final double killValue = paired ? share(row.killCount, total) : row.killCount;
					final int segment = Math.min(length,
						Math.max(1, (int) Math.round(barMax * killValue / scale)));
					g.setColor(KILL_COLOR);
					g.fillRect(barLeft + length - segment, barY, segment, BAR_HEIGHT);
				}

				if (runsOff)
				{
					tear(g, barLeft + length, barY, BAR_HEIGHT);
				}

				countX[i] = barLeft + length + COUNT_GAP;
			}
		}

		if (firstDamageRow > 0)
		{
			// Misses and splashes are not damage; keep them visibly apart from it.
			final int y = rowTop(firstDamageRow) - DIVIDER_HEIGHT / 2 - 1;
			g.setColor(DIVIDER_COLOR);
			g.drawLine(LEFT_PAD, y, getWidth() - RIGHT_PAD, y);
		}

		if (paired)
		{
			// Over the bars it is there to be compared against, but under the counts.
			drawCommunityLine(g, barLeft, barMax, scale);
		}

		for (int i = 0; i < rows.size(); i++)
		{
			final Row row = rows.get(i);
			if (row.count > 0)
			{
				g.setColor(row.color);
				g.drawString(Integer.toString(row.count), countX[i], rowTop(i) + fm.getAscent());
			}
		}
	}

	/**
	 * Everyone else's distribution, as a line running down the chart through the point on each row
	 * where their share of that damage falls. A bar that overshoots the line is a damage value you
	 * land more often than the rest of the community does, and one that stops short is the reverse.
	 *
	 * <p>The line covers the damage rows only. Misses and splashes are on a different scale and are
	 * marked with a tick instead, so their share cannot drag the curve off the chart.
	 */
	private void drawCommunityLine(Graphics2D g, int barLeft, int barMax, double scale)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		for (int i = 0; i < firstDamageRow; i++)
		{
			final int x = communityX(rows.get(i), barLeft, barMax, scale);
			final int barY = barTop(i);

			g.setColor(LINE_HALO_COLOR);
			g.setStroke(LINE_HALO_STROKE);
			g.drawLine(x, barY, x, barY + BAR_HEIGHT - 1);

			g.setColor(COMMUNITY_COLOR);
			g.setStroke(LINE_STROKE);
			g.drawLine(x, barY, x, barY + BAR_HEIGHT - 1);
		}

		if (firstDamageRow >= rows.size())
		{
			return;
		}

		final Path2D.Double path = new Path2D.Double();
		for (int i = firstDamageRow; i < rows.size(); i++)
		{
			final int x = communityX(rows.get(i), barLeft, barMax, scale);
			final int y = barTop(i) + BAR_HEIGHT / 2;

			if (i == firstDamageRow)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}

		g.setColor(LINE_HALO_COLOR);
		g.setStroke(LINE_HALO_STROKE);
		g.draw(path);

		g.setColor(COMMUNITY_COLOR);
		g.setStroke(LINE_STROKE);
		g.draw(path);

		// A dot per row, so a single row can still be read off the line where it runs near-vertical.
		for (int i = firstDamageRow; i < rows.size(); i++)
		{
			final int x = communityX(rows.get(i), barLeft, barMax, scale);
			final int y = barTop(i) + BAR_HEIGHT / 2;
			g.fillOval(x - 2, y - 2, 4, 4);
		}
	}

	/** Where a row's community share lands along the bar, clamped to the end of the chart. */
	private int communityX(Row row, int barLeft, int barMax, double scale)
	{
		final double value = share(Math.max(0, row.otherCount), otherTotal);
		final int length = Math.min(barMax, (int) Math.round(barMax * value / scale));
		return barLeft + Math.max(0, length);
	}

	/**
	 * Tears the end off a bar so it reads as "longer than the chart" rather than as a bar that
	 * happens to reach the edge.
	 */
	private void tear(Graphics2D g, int end, int barY, int barHeight)
	{
		g.setColor(getBackground());
		for (int notch = 0; notch < 3; notch++)
		{
			final int nx = end - 1 - notch * 3;
			g.drawLine(nx, barY, nx, barY + barHeight - 1);
		}
	}

	private static double share(int part, int whole)
	{
		return whole <= 0 ? 0 : (double) part / whole;
	}

	/** The tallest damage share in either series; what both are drawn against. */
	private double peakShare()
	{
		double highest = 0;
		for (int i = firstDamageRow; i < rows.size(); i++)
		{
			final Row row = rows.get(i);
			highest = Math.max(highest, share(row.count, total));
			highest = Math.max(highest, share(Math.max(0, row.otherCount), otherTotal));
		}
		return highest <= 0 ? 1 : highest;
	}

	private int rowTop(int index)
	{
		return TOP_PAD + index * ROW_HEIGHT
			+ (index >= firstDamageRow && firstDamageRow > 0 ? DIVIDER_HEIGHT : 0);
	}

	/** Top of the bar in a row, which is also what the community line is centred on. */
	private int barTop(int index)
	{
		return rowTop(index) + (ROW_HEIGHT - BAR_HEIGHT) / 2;
	}

	private int rowAt(int y)
	{
		for (int i = 0; i < rows.size(); i++)
		{
			final int top = rowTop(i);
			if (y >= top && y < top + ROW_HEIGHT)
			{
				return i;
			}
		}
		return -1;
	}

	private int widestCount()
	{
		int widest = 0;
		for (Row row : rows)
		{
			widest = Math.max(widest, row.count);
		}
		return widest;
	}
}

