	private JPanel wrap(JComponent inner)
	{
		final JPanel wrapper = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 4));
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
