		final CombatContext open = context(4151, CombatStyle.MELEE, 4, 100);
		final CombatContext prayed = AttackMatcherTest.builder(CombatStyle.MELEE, 4, 100)
			.targetOverheads(Collections.singletonList("PROTECT_FROM_MELEE"))
			.styleProtected(true)
			.build();

